-- 엠대시 제거.
-- 데이터에 "짧은 라벨 — 부연" 형태로 박혀 있다. 하이픈으로 바꾼다.
-- 원본 테이블은 그대로 두고 출력 시점에만 치환한다. 230군데를 손으로 고치지 않는다.
local function nodash(s)
  return (tostring(s or ""):gsub("\u{2014}", "-"))
end

-- 셀 조립. pool[t][H][L][G] 를 대체한다.
-- 라벨/값 쌍의 배열로 돌려준다. OOC 는 이어붙여 쓰고, 상태 패널 툴팁은 쌍째로 쓴다.
-- 완성된 문자열 한 덩이만 주면 툴팁 쪽에서 다시 쪼개야 하고, 라벨 규칙이 두 곳에 생긴다.
function getCellRows(t, H, L, G)
  local ty = T_TYPE[t];           if not ty then return nil end
  local at = T_ATT[H];            if not at then return nil end
  local al = T_ALLOW[H];          if not al then return nil end
  local g1 = T_GUILT[t];          if not g1 then return nil end
  local g2 = g1[G];               if not g2 then return nil end
  local fo = T_FORCE[H]
  local force = (H == 5 and L == 5)
      and "해당 없음 (전면 허용 상태)"
      or (fo and fo[L])
  if not (at[G] and al[L] and g2[L] and T_CONTRA[L] and force) then return nil end
  -- 유형 이름만으로는 모델이 무엇을 뜻하는지 확신할 수 없다.
  -- "집착·질투형" 다섯 글자에 담긴 것을 한 줄로 풀어준다.
  local desc = TYPE_DESC[t]
  return {
    { "성격",                          ty .. ((desc and desc ~= "") and (" - " .. desc) or "") },
    { "{{user}}를 대하는 태도",         nodash(at[G])       },
    { "신체 수용 정도",                 nodash(al[L])       },
    { "죄책감·욕망 심리",               nodash(g2[L])       },
    { "피임에 대한 생각",               nodash(T_CONTRA[L]) },
    { "수용 정도를 넘어갈 경우",         nodash(force)       },
  }
end

function getCell(t, H, L, G)
  local rows = getCellRows(t, H, L, G)
  if not rows then return nil end
  local out = {}
  for i = 1, #rows do out[i] = rows[i][1] .. ": " .. rows[i][2] end
  return table.concat(out, "\n")
end


