local function pickOne(pool)
  if not pool or #pool == 0 then return "" end
  return pool[math.random(#pool)]
end

-- 넷을 한 번에 깔 때 같은 값이 겹치지 않게 한다.
-- 넷 중 둘이 같은 페티시를 들고 서 있으면 무작위로 뽑았다는 것이 그대로 보인다.
-- 후보가 모자라면 겹치는 것을 허용한다. 목록 길이에 기대는 코드를 만들지 않는다.
local function pickUnique(pool, used)
  if not pool or #pool == 0 then return "" end
  for _ = 1, 16 do
    local v = pool[math.random(#pool)]
    if not used[v] then used[v] = true return v end
  end
  return pool[math.random(#pool)]
end

-- 나이 기본값.
--
-- 대역이 먼저고 자녀 단계는 그 안에서 순서만 만든다.
-- 자녀 나이를 그대로 따라가면 성인 자녀가 있는 여자가 오십을 넘는데,
-- 이 카드가 세우려는 인물상이 아니다.
-- 그래서 자녀 단계는 대역 안에서 몇 살 위인지만 정하고, 벗어나면 잘라낸다.
local AGE_MIN,    AGE_MAX    = 25, 34   -- 기혼
local AGE_BF_MIN, AGE_BF_MAX = 22, 28   -- 미혼·연인
local AGE_BY_KIDS = { 27, 28, 29, 31, 33, 34 }

local function clampAge(n, lo, hi)
  if n < lo then return lo end
  if n > hi then return hi end
  return n
end

-- 슬롯 번호로 조금씩 흔든다. 넷이 한 화면에 서므로 같은 나이로 줄지으면 눈에 띈다.
local function defAge(kids, i, bf)
  local jit = ((i * 7) % 5) - 2                     -- -2 ~ +2
  if bf then return clampAge(25 + jit, AGE_BF_MIN, AGE_BF_MAX) end
  return clampAge((AGE_BY_KIDS[kids] or 29) + jit, AGE_MIN, AGE_MAX)
end

-- 남자는 두어 살 위를 기본으로 둔다.
local function defHAge(wAge, i)
  return wAge + 2 + ((i * 3) % 4)                   -- +2 ~ +5
end

-- 추천 조합 버튼용. 슬롯으로 흔드는 대신 매번 새로 굴린다.
-- 같은 버튼을 여러 번 눌러 조합을 바꿔보는 자리라, 나이만 고정되어 있으면
-- 직업과 자녀가 통째로 갈렸는데 나이는 그대로 남는다.
local function rndAge(kids, bf)
  if bf then return clampAge(25 + math.random(-3, 3), AGE_BF_MIN, AGE_BF_MAX) end
  return clampAge((AGE_BY_KIDS[kids] or 29) + math.random(-2, 2), AGE_MIN, AGE_MAX)
end

local function rndHAge(wAge) return wAge + math.random(2, 5) end

-- 시나리오 프리셋 4종. 여자 4명 + 남편 4명을 한 번에 세팅한다.
--   type : 성격 유형
--   pick : 그 유형의 TYPE_PRESET 후보 중 몇 번을 쓸지 (직업·관계·남편·수치가 여기서 온다)
--   sc   : 시작 시 시뮬 출연 여부
