-- 자산 탭. NPC_PER 개씩 끊는다.
-- 탭 수를 고정하고 등분하면 개수가 늘어날수록 한 탭이 계속 길어져
-- 나중에는 탭을 눌러도 스크롤을 해야 한다. 밀도를 고정하고 탭이 늘게 둔다.
-- 범위를 손으로 적어두면 세트를 늘릴 때마다 두 군데를 고쳐야 하고,
-- 한쪽만 고치면 뒤쪽 자산이 어느 탭에도 안 뜬다.
local function npcCats(max, per)
  local t, n = {}, 1
  while n <= max do
    local e = math.min(n + per - 1, max)
    t[#t+1] = { n.."-"..e, n, e }
    n = e + 1
  end
  return t
end
CATS.FNPC = npcCats(FNPC_MAX, FNPC_PER)
CATS.MNPC = npcCats(MNPC_MAX, MNPC_PER)

-- 상태 수치는 0~300 연속값이다. pool 조회 시에만 단계로 압축한다.
--   호감 5단계 / 음란 5단계 / 죄책 3단계
-- 죄책은 값이 클수록 죄책감이 강하다. 시간이 갈수록 깎여나간다.

-- 단계 이름. 이 세 배열이 유일한 출처다.
-- 선택기 목록도, 화면 표시도, OOC 도 전부 여기서 뽑는다.
--
-- 이전에는 선택기용 5단계와 표시용 10단계가 따로 있었다.
-- 그래서 선택기에서 "호감"을 고르면 화면에는 "설렘"이 뜨는 식으로 어긋났다.
-- 표시 단계를 더 잘게 쪼개는 것도 실익이 없었다.
-- pool 은 5단계만 아는데 화면만 10단계로 나뉘면,
-- 65 → 95 처럼 표시는 바뀌는데 참조 셀은 그대로인 구간이 생긴다.
-- 단어가 바뀌었는데 행동은 그대로면 사용자가 시스템을 오해한다.
-- 세밀함은 옆에 붙는 0~300 숫자가 담당한다.
local AXIS_H = {"무관심","인식","관심","끌림","애정"}
local AXIS_L = {"순결","수줍음","개방","각성","탐닉"}
local AXIS_S = {"무심","위화","의심","심증","확증"}
local AXIS_G = {"죄책감","합리화","무감각"}   -- G1 → G3. 값이 클수록 죄책이 강하다

-- 수치 → pool 단계
local function toStage5(n)
  n = tonumber(n) or 0
  if n <=  60 then return 1
  elseif n <= 120 then return 2
  elseif n <= 180 then return 3
  elseif n <= 240 then return 4
  else                return 5 end
end

local function toStage3(n)   -- 죄책: 값이 클수록 G1
  n = tonumber(n) or 0
  if n >= 201 then return 1
  elseif n >= 101 then return 2
  else                return 3 end
end

-- 표시용 단계 이름. 좌표 산출과 같은 함수를 쓰므로 표시와 실제가 갈라지지 않는다.
local function affTier(n)   return AXIS_H[toStage5(n)] or AXIS_H[1] end
local function lewdTier(n)  return AXIS_L[toStage5(n)] or AXIS_L[1] end
local function guiltTier(n) return AXIS_G[toStage3(n)] or AXIS_G[1] end
local function suspTier(n)  return AXIS_S[toStage5(n)] or AXIS_S[1] end

-- 성(姓) 추출. 자녀 이름 앞에 아빠 성을 붙이는 데 쓴다.
-- Lua 문자열은 바이트 단위라 한글 한 자는 3바이트다.
-- 복성(남궁·황보 …)은 두 자이므로 먼저 걸러낸다.
local DOUBLE_SURNAME = {
  ["남궁"]=true, ["황보"]=true, ["제갈"]=true, ["사공"]=true, ["선우"]=true,
  ["서문"]=true, ["독고"]=true, ["동방"]=true, ["강전"]=true, ["어금"]=true,
}

local function surnameOf(full)
  full = full or ""
  local two = full:sub(1, 6)
  if DOUBLE_SURNAME[two] then return two end
  return full:sub(1, 3)
end

-- 단계 → 기본 수치 (수동 설정 시 구간 중앙값)
local MID5 = {30, 90, 150, 210, 270}
