-- 헬퍼
--------------------------------------------------
local function gv(tid, k, d)
  local v = getChatVar(tid, k)
  if v == nil or v == "" or v == "null" then return d end
  return v
end

local function gn(tid, k, d)
  return tonumber(gv(tid, k, tostring(d))) or d
end

-- 시나리오 한 세트를 슬롯에 심는다.
-- 인물 구성값은 TYPE_PRESET 에서 끌어오므로 여기와 저기가 어긋날 일이 없다.
-- 남편 자동 매칭을 켜두므로 여자N은 남편N을 참조한다.
local function fillScenario(tid, n)
  local sc = SCENARIO[n] or SCENARIO[1]
  -- 페티시·성적 취향은 넷이 겹치지 않게 뽑는다. 뽑은 것을 여기에 기억해둔다.
  local usedF, usedP = {}, {}
  for i, w in ipairs(sc.w) do
    local p  = "w"..i.."_"
    local h  = "h"..i.."_"
    local pz = TYPE_PRESET[w.type][w.pick or 1] or TYPE_PRESET[w.type][1]
    setChatVar(tid, p.."name",    w.name)
    setChatVar(tid, p.."type",    tostring(w.type))
    setChatVar(tid, p.."hus",     tostring(i))
    setChatVar(tid, p.."scene",   tostring(w.sc))
    setChatVar(tid, p.."affair",  "0")
    -- 페티시·성적 취향. 시나리오에 적어두면 그 값을, 없으면 무작위로 심는다.
    -- 비워두면 사용자가 여덟 칸을 손으로 채우기 전까지 두 축이 없는 것과 같다.
    setChatVar(tid, p.."fetish", w.fetish or pickUnique(FETISH_POOL, usedF))
    setChatVar(tid, p.."pref",   w.pref   or pickUnique(PREF_POOL,   usedP))
    setChatVar(tid, p.."job",     tostring(pz.job))
    setChatVar(tid, p.."rel",     tostring(pz.rel))
    setChatVar(tid, p.."kids",    tostring(pz.kids))
    setChatVar(tid, p.."kid_sex", pz.sex)
    -- 자녀가 없는 후보면 이름은 비운다. 나중에 자녀를 켰을 때 유령 이름이 남지 않게.
    setChatVar(tid, p.."kid_txt",
      (pz.sex ~= "") and ((w.kid ~= "" and w.kid) or KID_NAME[pz.sex] or "") or "")
    -- 나이. 시나리오에 age/hage 를 적어두면 그 값을, 없으면 자녀 단계에서 뽑는다.
    local wAge = w.age or defAge(pz.kids, i, w.single == 1)
    setChatVar(tid, p.."age",     tostring(wAge))
    setChatVar(tid, h.."age",     tostring(w.hage or defHAge(wAge, i)))
    setChatVar(tid, p.."aff",     tostring(pz.aff))
    setChatVar(tid, p.."lewd",    tostring(pz.lewd))
    setChatVar(tid, p.."guilt",   tostring(pz.guilt))
    setChatVar(tid, h.."name",    w.hname)
    setChatVar(tid, h.."relA",    tostring(pz.hA))
    setChatVar(tid, h.."relB",    tostring(pz.hB))
    setChatVar(tid, h.."relC",    tostring(pz.hC))
    -- hJob 은 시나리오에서 덮어쓸 수 있다.
    -- TYPE_PRESET 은 인물 단위로 만든 것이라, 넷을 한 화면에 모으면
    -- 남편 직업이 겹치는 일이 생긴다. pick 을 바꾸면 직업·관계·수치가 통째로
    -- 딸려와 시나리오 주제가 깨지므로 직업 한 칸만 갈아끼운다.
    setChatVar(tid, h.."job",     tostring(w.hJob or pz.hJob))
    setChatVar(tid, h.."user",    tostring(pz.hUser))
    -- 관계 형태. 시나리오에 single=1 이 붙은 인물만 미혼·연인이다.
    -- 후보(pick)는 자녀·직업·관계·hA/hB/hC 가 미혼 필터를 통과하는 것만 골라뒀다.
    setChatVar(tid, h.."single", (w.single == 1) and "1" or "0")
  end
  setChatVar(tid, "hus_auto", "1")
end

-- 슬롯 기본값 초기화
local function initDefaults(tid)
  if gv(tid, "setup_init", "0") == "1" then return end
  fillScenario(tid, 1)
  setChatVar(tid, "st_date",  "2026년 8월 6일 (목)")
  setChatVar(tid, "st_time",  "14:30")
  setChatVar(tid, "st_place", "-")
  setChatVar(tid, "hus_auto", "1")
  setChatVar(tid, "msj_ver", MSJ_VERSION or "?")   -- 1: 여자N이 남편N을 자동 참조 / 0: 수동 선택
  -- 0번은 인트로 화면이다. 여기까지 왔다는 것은 이미 [시작하겠습니다] 를 눌렀다는 뜻이므로
  -- 인트로로 되돌리지 않고 선택기(1번)로 보낸다.
  setChatVar(tid, "setup_num", "1")
  setChatVar(tid, "char_pop", "0")    -- 첫 설정은 인라인. 오버레이로 화면을 덮지 않는다
  -- 자산 코드 기본값. 슬롯 번호를 그대로 쓴다.
  -- FNPC1~4 / MNPC1~4 가 리네임 전 Female1~4 / Male1~4 자리이므로
  -- 아무것도 안 고르면 예전과 같은 얼굴이 나온다.
  for i = 1, 4 do
    setChatVar(tid, "w"..i.."_code", tostring(i))
    setChatVar(tid, "h"..i.."_code", tostring(i))
  end
  setChatVar(tid, "edit_target", "1")
  setChatVar(tid, "setup_init", "1")
end

-- 화면 표시용 문자열 갱신
-- 남편의 의심 성향. HR_A(애정) / HR_B(결함) 조합으로 판정한다.
-- HR_C(부재)는 성향이 아니라 조건이므로 여기서 보지 않는다. 배수로만 작동한다.
-- 해외에 있는 의처증 남편은 여전히 의처증이고, 다만 볼 기회가 없을 뿐이다.
local SUSP_TYPE = { "감시형", "주시형", "둔감형", "자기문제형" }
local SUSP_DESC = {
  "근거 없이도 의심한다. 계속 확인하고 잘 물러서지 않는다",
  "아끼기 때문에 잘 본다. 작은 변화를 잡아내나 결론짓기를 꺼린다",
  "애초에 보고 있지 않다. 늦게 알아채고 알면 크게 터진다",
  "자기도 켕기는 것이 있다. 눈치채도 물을 자격이 없어 눈을 돌린다",
}
local SUSP_MULT = { 1.5, 1.2, 0.5, 0.7 }

-- 성향 × 단계. 셀에 나가는 유일한 의심 정보다.
-- 성향 이름도 수치도 OOC 에 싣지 않는다. 여기 한 줄이 그 둘을 대신한다.
-- 곡선이 넷 다 다르다. 감시형은 처음부터 끝까지 직선으로 조이고,
-- 주시형은 S4 에서 오히려 조용해지며, 둔감형은 S5 에서 한꺼번에 터지고,
-- 자기문제형만 끝까지 안 터지고 덮는 쪽으로 닫힌다.
local T_SUSP = {
  { -- 감시형
    "평소처럼 행선지와 귀가 시간을 묻는다. 특정한 의심은 아직 없다",
    "답이 늦으면 다시 묻는다. 연락 간격이 짧아진다",
    "말한 일정을 뒤에서 확인한다. 어긋난 것을 찾아 되짚는다",
    "휴대폰과 옷과 소지품을 뒤진다. 나온 게 없어도 멈추지 않는다",
    "남자 이름을 대며 추궁한다. 뒤를 밟거나 사람을 붙인다",
  },
  { -- 주시형
    "달라진 데가 없는지 살핀다. 의심이 아니라 원래 잘 보는 것이다",
    "표정이 예전 같지 않다고 말한다. 무슨 일 있냐고 묻는다",
    "넘어가던 것을 한 번 더 묻는다. 대답을 기억해뒀다가 나중에 맞춰본다",
    "짐작하면서도 묻지 못한다. 말수가 줄고 눈을 오래 둔다",
    "확신한 채 확인만 남겨둔다. 그래서 오히려 더 다정해진다",
  },
  { -- 둔감형
    "아무것도 눈치채지 못한다. 볼 생각 자체가 없다",
    "어긋난 것을 지나친다. 물어놓고 대답을 듣지 않는다",
    "남이 흘린 말에 잠깐 반응했다가 곧 잊는다",
    "반복되는 부재에 뒤늦게 짜증을 낸다. 의심보다 불편에 가깝다",
    "쌓인 정황을 한꺼번에 알아챈다. 늦은 만큼 크게 터진다",
  },
  { -- 자기문제형
    "자기 문제로 바빠 아내를 보지 않는다",
    "어렴풋이 느끼면서 모른 척한다",
    "짐작하면서도 묻지 않는다. 물으면 자기 쪽도 걸린다",
    "술김이나 홧김에 한 번 내뱉고 곧 물러선다",
    "알고도 덮는다. 혹은 자기 잘못과 맞바꾸려 든다",
  },
}

function suspType(tid, hi)
  local h = "h"..hi.."_"
  local a = gn(tid, h.."relA", 1)
  local b = gn(tid, h.."relB", 1)
  if b == 2            then return 1 end   -- 의처증·감시. 애정 상태를 덮어쓴다
  if b >= 3 and b <= 5 then return 4 end   -- 폭력·외도, 알코올, 도박
  if a <= 3            then return 2 end   -- 과보호, 애처가, 신혼
  return 3
end

-- HR_C. 성향은 그대로 두고 속도만 조절한다.
-- 입원·투병은 집에 있고 아내가 간병하므로 관찰 기회가 오히려 많다.
local ABSENT_MULT = { 1.0, 0.7, 0.6, 0.5, 0.7, 1.2 }
--                    없음 출장 주말 해외 교대 입원

function absentMult(tid, hi)
  return ABSENT_MULT[gn(tid, "h"..hi.."_relC", 1)] or 1.0
end

-- 여자 슬롯 → 그 남편의 최종 의심 배수
function suspMult(tid, a)
  local hi = gn(tid, "w"..a.."_hus", a)
  local m  = SUSP_MULT[suspType(tid, hi)] * absentMult(tid, hi)
  if m < 0.3 then m = 0.3 end
  if m > 2.0 then m = 2.0 end
  return m
end

-- 목록 값 하나를 글자로 바꾼다. 99 면 목록 대신 직접 입력한 문자열을 쓴다.
local function hLbl(tid, p, f, list, idx)
  if idx == CUSTOM_IDX then return gv(tid, p..f.."_txt", "직접 입력") end
  return list[idx] or "?"
end

-- 관계 형태. 남편 슬롯 n 이 남자친구면 true.
local function isBf(tid, hn)
  return gv(tid, "h"..hn.."_single", "0") == "1"
end

-- 여자 슬롯 i 기준. 자기 남편 슬롯의 상태를 따라간다.
local function wIsBf(tid, i)
  return isBf(tid, gn(tid, "w"..i.."_hus", i))
end

-- 미혼·연인일 때 갈아끼우는 문구.
-- 「아내」를 통째로 바꾸면 RELS 의 "아내 친구" "아내의 사촌" 처럼
-- {{user}} 의 아내를 가리키는 항목까지 뒤집히므로, 걸리는 구절만 집어서 바꾼다.
-- 「남편」은 이 블록 안에서 그 여자의 남자만 가리키므로 통째로 바꿔도 안전하다.
-- 「유부녀」 세 건은 전부 H1 구간(T_ATT · T_FORCE · TYPE_DESC)에 박혀 있어
-- 미혼 인물의 초반에 반드시 걸린다. 「임자 있는 몸」은 결혼 여부와 무관하게 통한다.
-- 긴 구절을 먼저 두고 짧은 단어를 뒤에 둔다. 순서가 바뀌면 앞 치환이 뒤를 깨뜨린다.
local BF_SUB = {
  { "유부녀로서 외간남자와", "임자 있는 몸으로 다른 남자와" },
  { "유부녀라는 사실을",     "임자 있는 몸이라는 사실을"    },
  { "유부녀의 기본형",       "연애 중인 여자의 기본형"      },
  { "유부녀인데",            "임자 있는 몸인데"             },
  { "바빠 아내를 보지",      "바빠 여자친구를 보지"         },
  { "의 불륜: ",             "의 바람: "                    },
  { "남편",                  "연인"                         },
}

local function bfText(t)
  for _, r in ipairs(BF_SUB) do t = t:gsub(r[1], r[2]) end
  return t
end

local function refreshLabels(tid)
  -- 이미 진행 중인 채팅은 initDefaults 를 지나쳐 왔으므로 코드가 비어 있다.
  -- 비어 있으면 슬롯 번호로 심는다. 이 한 줄로 기존 방이 그대로 굴러간다.
  for i = 1, 4 do
    if gv(tid, "w"..i.."_code", "") == "" then setChatVar(tid, "w"..i.."_code", tostring(i)) end
    if gv(tid, "h"..i.."_code", "") == "" then setChatVar(tid, "h"..i.."_code", tostring(i)) end
  end
  for i = 1, 4 do
    local p = "w"..i.."_"
    setChatVar(tid, p.."type_kr", TYPES[gn(tid, p.."type", 1)] or "?")
    -- 99번이면 목록 대신 사용자가 입력한 문자열을 쓴다
    local ji = gn(tid, p.."job", 1)
    local ri = gn(tid, p.."rel", 1)
    setChatVar(tid, p.."job_kr",
      (ji == CUSTOM_IDX) and gv(tid, p.."job_txt", "직접 입력") or (JOBS[ji] or "?"))
    setChatVar(tid, p.."rel_kr",
      (ri == CUSTOM_IDX) and gv(tid, p.."rel_txt", "직접 입력") or (RELS[ri] or "?"))
    local auto = gv(tid, "hus_auto", "1")
    local hi = (auto == "1") and i or gn(tid, p.."hus", i)
    setChatVar(tid, p.."hus", tostring(hi))
    setChatVar(tid, p.."hus_kr", gv(tid, "h"..hi.."_name", "?"))
    -- 자녀. 이름은 '성 없이' 저장하고 표시할 때 아빠 성을 붙인다.
    -- 전체 이름을 저장해두면 남편을 바꿨을 때 성이 옛 남편 것으로 남는다.
    local kd = gn(tid, p.."kids", 1)
    setChatVar(tid, p.."kids", tostring(kd))
    local kidGiven = gv(tid, p.."kid_txt", "")
    local kidFull  = ""
    if kd > 1 and kidGiven ~= "" then
      kidFull = surnameOf(gv(tid, "h"..hi.."_name", "")) .. kidGiven
    end
    setChatVar(tid, p.."kid_name", kidFull)
    local sx = gv(tid, p.."kid_sex", "")
    local stage = KIDS[kd] or "?"
    if kd > 1 then
      if     sx == "M" then stage = stage.." · 아들"
      elseif sx == "F" then stage = stage.." · 딸" end
    end
    setChatVar(tid, p.."kid_sex_kr",
      (kd > 1) and ((sx == "M") and "아들" or (sx == "F") and "딸" or "미지정") or "")
    setChatVar(tid, p.."kids_kr",
      (kidFull ~= "") and (kidFull.." ("..stage..")") or stage)
    -- 나이. 구버전 채팅에는 없는 값이라 여기서 채워둔다.
    -- 자녀 단계를 바꿔도 이미 들어 있는 나이는 건드리지 않는다. 손으로 고친 값이 지워진다.
    local ag = gn(tid, p.."age", defAge(kd, i, wIsBf(tid, i)))
    setChatVar(tid, p.."age",    tostring(ag))
    setChatVar(tid, p.."age_kr", ag.."세")
    -- 관계 형태. 남편 슬롯에 저장된 값을 여자 쪽에도 비춰둔다.
    local bf = wIsBf(tid, i)
    setChatVar(tid, p.."single",     bf and "1" or "0")
    setChatVar(tid, p.."single_kr",  bf and "미혼 · 연인" or "기혼")
    setChatVar(tid, p.."hus_label",  bf and "연인" or "남편")
    -- 페티시·성적 취향. 자유 입력이라 목록이 없다. 비어 있으면 "없음"으로 보인다.
    -- *_on 은 팝업이 초기화 칩을 조건부로 그리는 데 쓴다.
    -- 비어 있어도 여기서 다시 뽑지 않는다. 매 턴 도는 자리라, 지운 값이 곧바로
    -- 되살아나 [지우기] 버튼이 동작하지 않는 것처럼 보인다.
    local fx = gv(tid, p.."fetish", "")
    setChatVar(tid, p.."fetish_kr", (fx ~= "") and fx or "없음")
    setChatVar(tid, p.."fetish_on", (fx ~= "") and "1" or "0")
    local pf = gv(tid, p.."pref", "")
    setChatVar(tid, p.."pref_kr", (pf ~= "") and pf or "없음")
    setChatVar(tid, p.."pref_on", (pf ~= "") and "1" or "0")
    local af = gv(tid, p.."affair", "0")
    setChatVar(tid, p.."affair", af)
    setChatVar(tid, p.."affair_kr", (af == "1") and "진행 중" or "없음")
    local sc = gv(tid, p.."scene", "0")
    setChatVar(tid, p.."scene", sc)
    setChatVar(tid, p.."scene_kr", (sc == "1") and "출연" or "제외")
    -- 수치가 아직 없으면 기본값을 심는다.
    -- (구버전 채팅은 setup_init 이 이미 1이라 initDefaults 가 안 돈다)
    local av = gn(tid, p.."aff",   30)
    local lv = gn(tid, p.."lewd",  30)
    local gvl= gn(tid, p.."guilt",250)
    setChatVar(tid, p.."aff",   tostring(av))
    setChatVar(tid, p.."lewd",  tostring(lv))
    setChatVar(tid, p.."guilt", tostring(gvl))
    local hh, ll, gg = toStage5(av), toStage5(lv), toStage3(gvl)
    setChatVar(tid, p.."H", tostring(hh))
    setChatVar(tid, p.."L", tostring(ll))
    setChatVar(tid, p.."G", tostring(gg))
    -- 목록 카드에 붙는 요약. H1 L1 G1 같은 코드는 사용자에게 아무 의미가 없다.
    setChatVar(tid, p.."state_kr",
      affTier(av).." · "..lewdTier(lv).." · "..guiltTier(gvl))
    setChatVar(tid, p.."H_kr", affTier(av))
    setChatVar(tid, p.."L_kr", lewdTier(lv))
    setChatVar(tid, p.."G_kr", guiltTier(gvl))
  end
  for i = 1, 4 do
    local p = "h"..i.."_"
    local ai, bi, ci = gn(tid, p.."relA", 1), gn(tid, p.."relB", 1), gn(tid, p.."relC", 1)
    setChatVar(tid, p.."relA", tostring(ai))
    setChatVar(tid, p.."relB", tostring(bi))
    setChatVar(tid, p.."relC", tostring(ci))
    local a = hLbl(tid, p, "relA", HR_A, ai)
    local b = hLbl(tid, p, "relB", HR_B, bi)
    local c = hLbl(tid, p, "relC", HR_C, ci)
    setChatVar(tid, p.."relA_kr", a)
    setChatVar(tid, p.."relB_kr", b)
    setChatVar(tid, p.."relC_kr", c)
    -- 카드 요약: 의미 있는 항목만 이어붙인다
    local parts = { a }
    if b ~= "결함 없음"  then parts[#parts+1] = b end
    if c ~= "해당 없음"  then parts[#parts+1] = c end
    setChatVar(tid, p.."rel_kr", table.concat(parts, " · "))
    setChatVar(tid, p.."job_kr",  hLbl(tid, p, "job",  H_JOB,  gn(tid, p.."job",  1)))
    setChatVar(tid, p.."user_kr", hLbl(tid, p, "user", H_USER, gn(tid, p.."user", 1)))
    -- 의심 성향은 relA/relB 에서 파생된다. 저장하지 않고 매번 다시 구한다.
    local st = suspType(tid, i)
    setChatVar(tid, p.."susp_type", tostring(st))
    setChatVar(tid, p.."susp_kr",   SUSP_TYPE[st])
    setChatVar(tid, p.."susp_desc", SUSP_DESC[st])
    -- 시작값은 성향과 무관하게 0이다. 성향 차이는 배수가 만든다.
    -- 시작값까지 다르게 두면 같은 성질이 두 번 반영된다.
    local sv = gn(tid, p.."susp", 0)
    setChatVar(tid, p.."susp",    tostring(sv))
    setChatVar(tid, p.."S",       tostring(toStage5(sv)))
    setChatVar(tid, p.."S_kr",    suspTier(sv))
    setChatVar(tid, p.."susp_act", (T_SUSP[st] or {})[toStage5(sv)] or "")
    -- 이 남자를 참조하는 여자 (표시용)
    -- 예전에는 이 블록이 아래 여자 미러 루프 안에 있었다. 거기서는 p 가 "w{i}_" 라
    -- h{i}_wife_kr 이 만들어진 적이 없었고, 남편 편집 팝업의 아내 칸이 늘 비어 있었다.
    local wives = {}
    for k = 1, 4 do
      if gn(tid, "w"..k.."_hus", k) == i then wives[#wives+1] = gv(tid, "w"..k.."_name", "?") end
    end
    setChatVar(tid, p.."wife_kr", (#wives > 0) and table.concat(wives, ", ") or "없음")
    local hag = gn(tid, p.."age", defHAge(gn(tid, "w"..i.."_age", 32), i))
    setChatVar(tid, p.."age",    tostring(hag))
    setChatVar(tid, p.."age_kr", hag.."세")
    setChatVar(tid, p.."single_kr",  isBf(tid, i) and "남자친구" or "남편")
    setChatVar(tid, p.."wife_label", isBf(tid, i) and "여자친구" or "아내")
  end
  -- 여자 슬롯에서 남편 의심을 바로 읽을 수 있게 미러링한다.
  -- 카드·상태 패널·셀이 전부 여자 슬롯 기준으로 돌아가므로, 매번 w{n}_hus 를
  -- 거치게 하면 같은 조회가 네 군데로 흩어진다.
  for i = 1, 4 do
    local p  = "w"..i.."_"
    local hp = "h"..gn(tid, p.."hus", i).."_"
    setChatVar(tid, p.."susp",      gv(tid, hp.."susp",      "0"))
    setChatVar(tid, p.."S",         gv(tid, hp.."S",         "1"))
    setChatVar(tid, p.."S_kr",      gv(tid, hp.."S_kr",      "무심"))
    setChatVar(tid, p.."hsusp_kr",  gv(tid, hp.."susp_kr",   "?"))
    setChatVar(tid, p.."hsusp_desc",gv(tid, hp.."susp_desc", ""))
    setChatVar(tid, p.."hsusp_act", gv(tid, hp.."susp_act",  ""))
  end

  -- 편집 대상 미러 (CBS 중첩 회피용)
  local t = gn(tid, "edit_target", 1)
  for _, k in ipairs({"name","age","age_kr","type_kr","job_kr","rel_kr","hus_kr","kids_kr","affair","affair_kr","fetish","fetish_kr","fetish_on","pref","pref_kr","pref_on","single","single_kr","hus_label","scene","scene_kr","state_kr","H","L","G","H_kr","L_kr","G_kr","aff","lewd","guilt","S","S_kr","susp","code"}) do
    setChatVar(tid, "cw_"..k, gv(tid, "w"..t.."_"..k, ""))
  end
  for _, k in ipairs({"name","age","age_kr","rel_kr","relA_kr","relB_kr","relC_kr","job_kr","user_kr","wife_kr","single","single_kr","wife_label","code"}) do
    setChatVar(tid, "ch_"..k, gv(tid, "h"..t.."_"..k, ""))
  end

  -- 주 대상 미러 = 시뮬에 출연 중인 첫 번째 인물
  local a = 0
  for i = 1, 4 do
    if gv(tid, "w"..i.."_scene", "0") == "1" then a = i break end
  end
  if a == 0 then a = 1 end
  setChatVar(tid, "active_w", tostring(a))
  for _, k in ipairs({"name","type_kr","job_kr","rel_kr","hus_kr","kids_kr","affair","affair_kr","scene","scene_kr","state_kr"}) do
    setChatVar(tid, "aw_"..k, gv(tid, "w"..a.."_"..k, ""))
  end
  setChatVar(tid, "msj_ver", MSJ_VERSION or "?")
  -- 정규식이 CBS 로 직접 읽는 값들이다. 비어 있으면 class 가 "msj-sz-" 로 잘려
  -- 크기 규칙이 통째로 안 걸린다. 기본값을 실제 변수에 심어둔다.
  for _, k in ipairs({"msj_img", "msj_tap", "msj_nsfw"}) do
    setChatVar(tid, k, setOpt(tid, k))
  end
  setChatVar(tid, "hus_auto_kr",
    (gv(tid, "hus_auto", "1") == "1") and "자동 (슬롯 번호 일치)" or "수동 지정")

  -- 시뮬 출연 명단
  local names, cnt = {}, 0
  for i = 1, 4 do
    if gv(tid, "w"..i.."_scene", "0") == "1" then
      cnt = cnt + 1
      names[#names+1] = gv(tid, "w"..i.."_name", "?")
    end
  end
  setChatVar(tid, "scene_count", tostring(cnt))
  setChatVar(tid, "scene_names", (cnt > 0) and table.concat(names, ", ") or "없음")

  setChatVar(tid, "aw_pool_key",
    gv(tid,"w"..a.."_type","1").."-"..gv(tid,"w"..a.."_H","1")
    .."-"..gv(tid,"w"..a.."_L","1").."-"..gv(tid,"w"..a.."_G","1"))
end

local function redraw(tid)
  initDefaults(tid)   -- 아직 초기화 전이면 여기서 심는다 (setup_init 가드가 있어 중복 실행은 무해)
  refreshLabels(tid)
  pcall(reloadDisplay, tid)
end

--------------------------------------------------
-- HTML 선택 화면 (alertSelect 대체)
--------------------------------------------------
-- 목록을 칩 그리드 HTML로 조립해 sel_html 에 넣는다.
-- 항목마다 risu-trigger="pickIdxN" 이 붙고, 클릭하면 sel_key 변수에 N이 저장된다.
-- 카테고리가 있는 목록은 상단에 탭이 붙고, pickCatN 으로 전환한다.
-- 트리거 세트(pickIdx1~60 / pickCat1~12)는 모든 목록이 공유한다.

-- 자산 목록이 60 을 넘어도 트리거가 따라 늘어난다.
-- 고정값으로 두면 FNPC_MAX 를 올린 날 뒷번호가 눌리지 않는다.
local SEL_MAX = math.max(60, FNPC_MAX, MNPC_MAX)
local CAT_MAX = 12

-- 리스트 ID → 실제 배열
-- 다른 슬롯이 이미 쓰고 있는 자산 코드.
-- 같은 얼굴 둘을 굳이 막을 이유는 수치 쪽에는 없다. 태그가 슬롯 이름으로
-- 갈라져 들어오니 섞이지도 않는다. 막는 이유는 화면 쪽이다.
-- 설정 화면과 픽커에 같은 얼굴이 둘 뜨면 어느 쪽이 누구인지 못 읽는다.
--
-- pre 는 "w" 또는 "h". 이름공간이 갈려 있어 여자와 남자를 교차로 볼 필요가 없다.
local function codeTaken(tid, pre, self)
  local t = {}
  for i = 1, 4 do
    if i ~= self then t[gn(tid, pre..i.."_code", i)] = i end
  end
  return t
end

local function listOf(tid, id)
  if id == "TYPES"  then return TYPES  end
  if id == "JOBS"   then return JOBS   end
  if id == "RELS"   then return RELS   end
  if id == "HR_A"   then return HR_A   end
  if id == "HR_B"   then return HR_B   end
  if id == "HR_C"   then return HR_C   end
  if id == "KIDS"   then return KIDS   end
  if id == "H_JOB"  then return H_JOB  end
  if id == "H_USER" then return H_USER end
  if id == "AXIS_H" then return AXIS_H end
  if id == "AXIS_L" then return AXIS_L end
  if id == "AXIS_G" then return AXIS_G end
  if id == "AXIS_S" then return AXIS_S end
  -- 페티시·성적 취향은 자유 입력이 원칙이나, 후보 목록을 그대로 칩으로 깐다.
  -- 매번 손으로 쓰는 것보다 스물몇 개 중에서 고르는 쪽이 빠르다.
  -- 고르면 목록 번호가 아니라 문자열이 저장된다 (applyPick 이 갈라 처리한다).
  if id == "FETISH" then return FETISH_POOL end
  if id == "PREF"   then return PREF_POOL   end
  -- 자산 목록은 값이 없다. 개수만 있으면 되고 화면에는 사진이 나간다.
  if id == "FNPC" or id == "MNPC" then
    local t = {}
    for i = 1, ((id == "FNPC") and FNPC_MAX or MNPC_MAX) do t[i] = tostring(i) end
    return t
  end
  if id == "WIVES" then
    local hn = gn(tid, "edit_target", 1)
    local t = {}
    for i = 1, 4 do
      local tag = (gn(tid, "w"..i.."_hus", i) == hn)
                  and ("|"..gv(tid, "h"..hn.."_wife_label", "아내").."|") or ""
      t[i] = tag..gv(tid, "w"..i.."_name", "?")
          .." · "..gv(tid, "w"..i.."_type_kr", "?").."형"
          .." · "..gv(tid, "w"..i.."_job_kr", "?")
    end
    return t
  end
  if id == "HUS" then
    local wn = gn(tid, "edit_target", 1)
    local mine = gn(tid, "w"..wn.."_hus", wn)
    local t = {}
    for i = 1, 4 do
      -- 배지는 그 여자의 관계 형태를 따른다. 미혼인데 「남편」이 붙으면 안 된다.
      local tag = (i == mine)
                  and ("|"..gv(tid, "w"..wn.."_hus_label", "남편").."|") or ""
      t[i] = tag..gv(tid, "h"..i.."_name", "?")
          .." · "..gv(tid, "h"..i.."_rel_kr", "?")
          .." · "..gv(tid, "h"..i.."_job_kr", "?")
    end
    return t
  end
  return {}
end

-- 목록 상단 동작 버튼. 카테고리 탭과 같은 줄에 앉지만 카테고리가 아니다.
-- 색은 활성 탭(.SCAT88-tab-on)의 보라 구성을 그대로 옮긴 것이다.
-- 형태가 같고 색만 다르므로 "선택된 탭"이 아니라 "다른 종류의 버튼"으로 읽힌다.
-- 인라인에 !important 를 붙이는 이유는 .SCAT88-tab 규칙이 전부 !important 라서다.
-- <span> 대신 <b> 를 쓰는 것은 editDisplay 가 인라인 style 이 붙은 span 을
-- 잘라내는 사례가 있어서다. 설정 팝업의 선택 화면은 editDisplay 로 그려진다.
local ACT_TONE = {
  green = {"#5FE3A8", "63,214,154",  "30,140,100"},
  amber = {"#E8C26A", "232,194,106", "150,110,30"},
}

local function actTab(trigger, label, tone)
  local c = ACT_TONE[tone] or ACT_TONE.green
  return '<b class="SCAT88-tab" risu-trigger="'..trigger..'" style="'
    .. 'color:'..c[1]..' !important;'
    .. 'background:linear-gradient(150deg,rgba('..c[2]..',0.30),rgba('..c[3]..',0.14) 72%) !important;'
    .. 'border-color:rgba('..c[2]..',0.62) !important;'
    .. 'box-shadow:0 0 12px rgba('..c[2]..',0.22),inset 0 1px 0 rgba(255,255,255,0.10) !important;'
    .. '">'..label..'</b>'
end

-- 켜짐/꺼짐이 있는 탭. 선택된 쪽은 활성 탭과 같은 보라로 보인다.
-- 동작 탭(actTab)은 누르면 실행되는 버튼이고, 이쪽은 값이 남는 선택지다.
local function selTab(trigger, label, on)
  return '<span class="SCAT88-tab'..(on and " SCAT88-tab-on" or "")
      ..'" risu-trigger="'..trigger..'">'..label..'</span>'
end

local function actionTabs(tid, id)
  if id == "JOBS" then
    return actTab("setWJobText", "＋ 직접 입력", "green")
  elseif id == "RELS" then
    return actTab("setWRelText", "＋ 직접 입력", "green")
  elseif id == "HR_A" then
    return actTab("setHRelAText", "＋ 직접 입력", "green")
  elseif id == "HR_B" then
    return actTab("setHRelBText", "＋ 직접 입력", "green")
  elseif id == "HR_C" then
    return actTab("setHRelCText", "＋ 직접 입력", "green")
  elseif id == "H_JOB" then
    return actTab("setHJobText", "＋ 직접 입력", "green")
  elseif id == "AXIS_H" or id == "AXIS_L" or id == "AXIS_G" or id == "AXIS_S" then
    return actTab("setStageNum", "＋ 숫자 직접 입력", "green")
  elseif id == "FETISH" then
    -- 목록에 없는 것을 쓰거나, 아예 비우거나, 다시 뽑거나. 셋 다 여기서 한다.
    return actTab("setWFetish",   "＋ 직접 입력", "green")
        .. actTab("rollWFetish",  "↻ 다시 뽑기", "amber")
        .. actTab("clearWFetish", "× 비우기",    "amber")
  elseif id == "PREF" then
    return actTab("setWPref",   "＋ 직접 입력", "green")
        .. actTab("rollWPref",  "↻ 다시 뽑기", "amber")
        .. actTab("clearWPref", "× 비우기",    "amber")
  elseif id == "KIDS" then
    -- '없음'이면 이름도 성별도 의미가 없으므로 아무것도 띄우지 않는다.
    local wn = gn(tid, "edit_target", 1)
    if gn(tid, "w"..wn.."_kids", 1) <= 1 then return "" end
    local sx = gv(tid, "w"..wn.."_kid_sex", "")
    return actTab("setWKidName", "＋ 이름 입력", "green")
        .. selTab("setKidSexM", "남아", sx == "M")
        .. selTab("setKidSexF", "여아", sx == "F")
  elseif id == "FNPC" then
    -- FNPC_MAX 를 아직 안 올린 채로 새 세트를 급히 쓸 때의 탈출구다.
    return actTab("setWCodeText", "＋ 번호 직접 입력", "green")
  elseif id == "MNPC" then
    return actTab("setHCodeText", "＋ 번호 직접 입력", "green")
  elseif id == "H_USER" then
    return actTab("setHUserText", "＋ 직접 입력", "green")
  elseif id == "HUS" then
    -- 자동 매칭은 여자 화면에서 남편을 고르려는 바로 그 순간에 필요하다.
    -- 남편 슬롯 메뉴에 두면 고르려다 막히고 나서야 어디서 풀어야 하는지 찾게 된다.
    -- 켜고 끄는 것이 아니라 둘 중 하나를 고르는 것이다.
    -- 한 칸짜리 버튼이면 지금 어느 쪽인지와 누르면 뭐가 되는지를 한 줄에 담아야 해서
    -- 라벨이 길어지고, 읽는 사람이 두 번 해석해야 한다.
    local auto = gv(tid, "hus_auto", "1") == "1"
    return selTab("setHusAuto",   "자동 매칭", auto)
        .. selTab("setHusManual", "수동 지정", not auto)
  end
  return ""
end

-- 현재 상태로 선택 화면 HTML 재조립
local function renderPicker(tid)
  local id   = gv(tid, "sel_list", "")
  local key  = gv(tid, "sel_key", "")
  local list = listOf(tid, id)
  local cur  = gn(tid, key, 0)
  local cats = CATS[id]
  local cat  = gn(tid, "sel_cat", 1)

  -- 페티시·성적 취향은 번호가 아니라 문자열로 저장된다.
  -- 지금 값이 목록 몇 번인지 되짚어야 그 칩이 켜진 채로 열린다.
  if id == "FETISH" or id == "PREF" then
    local now = gv(tid, key, "")
    cur = 0
    for i, v in ipairs(list) do
      if v == now then cur = i break end
    end
  end

  -- 탭
  local tabs = ""
  if cats then
    local tb = {}
    for i, c in ipairs(cats) do
      local on = (i == cat) and " SCAT88-tab-on" or ""
      tb[#tb+1] = '<span class="SCAT88-tab'..on..'" risu-trigger="pickCat'..i..'">'..c[1]..'</span>'
    end
    tabs = table.concat(tb)
  end
  tabs = tabs .. actionTabs(tid, id)
  setChatVar(tid, "sel_tabs", tabs)
  -- 카테고리가 없어도 동작 버튼만으로 탭 줄이 필요할 수 있다
  setChatVar(tid, "sel_hastab", (tabs ~= "") and "1" or "0")

  -- 표시할 인덱스 목록 산출
  local idxs = {}
  if cats and cats[cat] then
    local c = cats[cat]
    if type(c[2]) == "table" then
      for _, n in ipairs(c[2]) do idxs[#idxs+1] = n end
    else
      for n = c[2], c[3] do idxs[#idxs+1] = n end
    end
  else
    for n = 1, #list do idxs[#idxs+1] = n end
  end

  -- 관계 형태가 남자친구면 결혼 전제 항목을 뺀다.
  -- 남편 목록(HR_*)은 편집 중인 남편 슬롯을, 여자 목록은 그 여자의 남편 슬롯을 본다.
  local wed = WED_ONLY[id]
  if wed then
    local t  = gn(tid, "edit_target", 1)
    local hList = (id == "HR_A" or id == "HR_B" or id == "HR_C"
                or id == "H_JOB" or id == "H_USER")
    local bf = hList and isBf(tid, t) or wIsBf(tid, t)
    if bf then
      local drop = {}
      for _, n in ipairs(wed) do drop[n] = true end
      local keep = {}
      for _, n in ipairs(idxs) do
        if not drop[n] then keep[#keep+1] = n end
      end
      idxs = keep
    end
  end

  -- 자산 그리드. 글자 칩 대신 프로필 사진을 깐다.
  -- 사진과 트리거가 같은 n 에서 나오므로 얼굴과 번호가 어긋날 수 없다.
  --
  -- 인라인 style 을 쓰는 이유는 actTab 과 같다. 새 클래스를 만들면 그 규칙이
  -- 카드 CSS 와 앱 CSS 중 어느 층에 앉느냐에 따라 사용자마다 다르게 보인다.
  -- span 대신 b 를 쓰는 것도 같은 이유다. editDisplay 가 style 붙은 span 을 자른다.
  if id == "FNPC" or id == "MNPC" then
    local pre   = (id == "FNPC") and "FNPC" or "MNPC"
    local taken = codeTaken(tid, (id == "FNPC") and "w" or "h", gn(tid, "edit_target", 1))
    local b2 = {}
    for _, n in ipairs(idxs) do
      local on  = (n == cur)
      local off = taken[n] and not on
      -- 점유된 칸은 트리거 자체를 빼고 흑백으로 둔다.
      -- 눌러도 아무 일 없게 하는 것보다, 누를 수 없어 보이는 편이 낫다.
      -- 투명도를 낮추면 얼굴이 뭉개져 누가 그 자리를 쓰는지 안 보인다.
      -- 흑백은 색만 빠지고 형태는 남아서, 이미 쓰는 얼굴을 알아볼 수 있다.
      b2[#b2+1] = '<b'..(off and '' or ' risu-trigger="pickIdx'..n..'"')..' style="'
        .. (off and 'filter:grayscale(1);' or '')
        .. 'display:block;overflow:hidden;border-radius:9px;aspect-ratio:3/2;'
        -- 사진을 img 가 아니라 배경으로 깐다.
        -- img 를 겹치려면 절대 위치가 필요한데, 인라인 style 의 position 이
        -- 살아남지 못해 배지가 흐름에 남고 위쪽 한 줄을 통째로 먹었다.
        -- 배경으로 두면 겹침이 공짜로 되고 비율도 background-size 가 잡는다.
        .. 'background-image:url({{raw::'..pre..n..'_profile}});'
        .. 'background-size:cover;background-position:center;background-repeat:no-repeat;'
        .. 'background-color:rgba(0,0,0,0.35);'
        .. 'border:2px solid '..(on and 'rgba(154,110,255,0.92)' or 'rgba(255,255,255,0.10)')..';'
        .. (off and 'cursor:default;' or '')
        .. (on and 'box-shadow:0 0 12px rgba(154,110,255,0.30);' or '')
        .. '">'
        -- 배지는 흐름에 그대로 둔다. inline-block + margin 이면 좌상단에 앉는다.
        .. '<b style="display:inline-block;margin:4px;padding:1px 5px;'
        .. 'border-radius:5px;font-size:10px;line-height:1.5;'
        .. 'background:rgba(0,0,0,0.62);'
        .. 'color:'..(on and '#C9A6FF' or '#D8D2CC')..';">'..n
        .. (off and ' · 사용중' or '')..'</b></b>'
    end
    setChatVar(tid, "sel_html",  table.concat(b2))
    setChatVar(tid, "sel_count", tostring(#idxs))
    setChatVar(tid, "sel_total", tostring(#list))
    return
  end

  -- 칩
  -- 문장형 목록. 페티시·성적 취향은 항목이 짧은 낱말이 아니라 구와 문장이라
  -- 기본 칩(한 줄 전제)에 넣으면 뒤가 잘리거나 칸을 삐져나간다.
  -- 줄바꿈을 허용하는 변형 클래스를 덧붙인다. 기본 칩 규칙은 건드리지 않는다.
  local wide = (id == "FETISH" or id == "PREF") and " SCAT88-chip-w" or ""

  local buf = {}
  for _, i in ipairs(idxs) do
    local v = list[i]
    if v then
      local on = (i == cur) and " SCAT88-chip-on" or ""
      -- "|태그|본문" 형식이면 태그를 배지로 뽑아낸다
      local tag, body = v:match("^|([^|]+)|(.*)$")
      if tag then
        v = '<span class="SCAT88-tag">'..tag..'</span>'..body
      end
      local desc = (id == "TYPES") and TYPE_DESC[i] or nil
      if desc then
        -- 설명이 있는 목록은 두 줄 칩으로 그린다 (툴팁은 스크롤 컨테이너에서 잘린다)
        buf[#buf+1] = '<span class="SCAT88-chip SCAT88-chip-d'..on..'" risu-trigger="pickIdx'..i..'">'
                   .. '<span class="SCAT88-chiphd">'
                   .. '<span class="SCAT88-chipnum">'..string.format("%02d", i)..'</span>'
                   .. '<span class="SCAT88-chiptx">'..v..'</span></span>'
                   .. '<span class="SCAT88-chipdesc">'..desc..'</span></span>'
      else
        buf[#buf+1] = '<span class="SCAT88-chip'..wide..on..'" risu-trigger="pickIdx'..i..'">'
                   .. '<span class="SCAT88-chipnum">'..string.format("%02d", i)..'</span>'
                   .. '<span class="SCAT88-chiptx">'..v..'</span></span>'
      end
    end
  end
  local chips = table.concat(buf)
  -- 자녀는 단계를 고른 뒤 이름 입력이 이어져야 해서 전용 async 트리거를 쓴다
  if id == "KIDS" then chips = chips:gsub("pickIdx", "pickKid") end
  setChatVar(tid, "sel_html", chips)
  setChatVar(tid, "sel_count", tostring(#idxs))
  setChatVar(tid, "sel_total", tostring(#list))
end

local function openPicker(tid, id, key, title, backNum, cols)
  initDefaults(tid)
  refreshLabels(tid)
  -- 상태축은 현재 수치에서 단계를 역산해 하이라이트한다
  local wpre = "w"..gn(tid, "edit_target", 1).."_"
  if     key == "__stageH" then setChatVar(tid, key, tostring(toStage5(gn(tid, wpre.."aff",   30))))
  elseif key == "__stageL" then setChatVar(tid, key, tostring(toStage5(gn(tid, wpre.."lewd",  30))))
  elseif key == "__stageG" then setChatVar(tid, key, tostring(toStage3(gn(tid, wpre.."guilt",250))))
  elseif key == "__stageS" then setChatVar(tid, key, tostring(toStage5(gn(tid, "h"..gn(tid, wpre.."hus", 1).."_susp", 0))))
  end
  setChatVar(tid, "sel_list",  id)
  setChatVar(tid, "sel_key",   key)
  setChatVar(tid, "sel_title", title)
  setChatVar(tid, "sel_back",  tostring(backNum))
  setChatVar(tid, "sel_cols",  tostring(cols or 2))

  -- 현재 값이 속한 카테고리를 열어둔다
  local cat, cats, cur = 1, CATS[id], gn(tid, key, 0)
  if cats then
    for i, c in ipairs(cats) do
      if type(c[2]) == "table" then
        for _, n in ipairs(c[2]) do
          if n == cur then cat = i break end
        end
      elseif cur >= c[2] and cur <= c[3] then
        cat = i break
      end
    end
  end
  setChatVar(tid, "sel_cat", tostring(cat))

  renderPicker(tid)
  setChatVar(tid, "setup_num", "6")
  pcall(reloadDisplay, tid)
end

-- 항목 선택 확정
local function applyPick(tid, n)
  local key = gv(tid, "sel_key", "")
  local tot = gn(tid, "sel_total", 0)
  if key == "" or n < 1 or n > tot then return end
  -- 페티시·성적 취향은 번호가 아니라 고른 문자열을 그대로 심는다.
  -- 목록은 시작값을 뽑는 후보일 뿐이라, 나중에 항목을 더하거나 순서를 바꿔도
  -- 이미 저장된 인물의 값이 다른 것으로 바뀌면 안 된다.
  local id = gv(tid, "sel_list", "")
  if id == "FETISH" or id == "PREF" then
    local v = (id == "FETISH") and FETISH_POOL[n] or PREF_POOL[n]
    if v then setChatVar(tid, key, v) end
    setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
    redraw(tid)
    return
  end
  -- 상태축은 단계 → 수치 변환
  local wpre = "w"..gn(tid, "edit_target", 1).."_"
  if key == wpre.."hus" then
    -- 자동 모드에서 고르면 다음 refreshLabels 가 슬롯 번호로 덮어써 선택이 사라진다.
    -- 고른다는 행위 자체가 수동 의사이므로 여기서 전환한다. setHWife 와 같은 처리다.
    setChatVar(tid, "hus_auto", "0")
    -- 1:1 스왑. 여자 wn 의 남편을 n 으로 바꾸고, n 을 쓰던 여자가 원래 남편을 받는다.
    local wn = gn(tid, "edit_target", 1)
    local oldOwner = nil
    for i = 1, 4 do
      if i ~= wn and gn(tid, "w"..i.."_hus", i) == n then oldOwner = i break end
    end
    local wOldHus = gn(tid, "w"..wn.."_hus", wn)

    setChatVar(tid, "w"..wn.."_hus", tostring(n))
    if oldOwner then
      setChatVar(tid, "w"..oldOwner.."_hus", tostring(wOldHus))
    end
    setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
    redraw(tid)
    return
  end
  if key == "__wife" then
    -- 1:1 스왑. 남편 hn 의 아내를 여자 n 으로 바꾼다.
    -- 여자 n 이 원래 쓰던 남편은, hn 의 원래 아내가 넘겨받는다.
    local hn = gn(tid, "edit_target", 1)
    local oldWife = nil                       -- 지금 hn 을 쓰는 여자
    for i = 1, 4 do
      if gn(tid, "w"..i.."_hus", i) == hn then oldWife = i break end
    end
    local nOldHus = gn(tid, "w"..n.."_hus", n)  -- 여자 n 이 쓰던 남편

    setChatVar(tid, "w"..n.."_hus", tostring(hn))
    if oldWife and oldWife ~= n then
      setChatVar(tid, "w"..oldWife.."_hus", tostring(nOldHus))
    end
    setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
    redraw(tid)
    return
  end
  -- 자산 코드. 트리거를 빼두어 여기까지 오지 않지만, 화면이 갱신되기 전에
  -- 눌린 경우가 있어 저장 직전에 한 번 더 본다.
  if key:match("^[wh]%d_code$") then
    local pre = key:sub(1, 1)
    if codeTaken(tid, pre, gn(tid, "edit_target", 1))[n] then
      alertError(tid, "이미 다른 슬롯이 쓰고 있는 에셋입니다")
      return
    end
  end
  if key == "__stageH" then
    setChatVar(tid, wpre.."aff",   tostring(MID5[n] or 30))
  elseif key == "__stageL" then
    setChatVar(tid, wpre.."lewd",  tostring(MID5[n] or 30))
  elseif key == "__stageG" then
    setChatVar(tid, wpre.."guilt", tostring(MID3[n] or 250))
  elseif key == "__stageS" then
    -- 의심만 남편 슬롯에 쓴다
    setChatVar(tid, "h"..gn(tid, wpre.."hus", 1).."_susp", tostring(MID5[n] or 0))
  else
    setChatVar(tid, key, tostring(n))
  end
  setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
  redraw(tid)
end

for i = 1, SEL_MAX do
  _G["pickIdx"..i] = function(tid) applyPick(tid, i) end
end

-- 탭 전환
local function switchCat(tid, n)
  local cats = CATS[gv(tid, "sel_list", "")]
  if not cats or not cats[n] then return end
  setChatVar(tid, "sel_cat", tostring(n))
  renderPicker(tid)
  pcall(reloadDisplay, tid)
end

for i = 1, CAT_MAX do
  _G["pickCat"..i] = function(tid) switchCat(tid, i) end
end

function pickCancel(tid)
  setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
  redraw(tid)
end

--------------------------------------------------
-- 화면 전환
--------------------------------------------------
-- onStart 는 파일 하단 [주입] 구역에서 정의한다

-- 인트로 화면(0번)의 [시작하겠습니다]. 변수가 태어나는 유일한 지점이다.
--
-- 새 방을 열기만 한 시점에는 LUA 가 한 번도 돌지 않아 변수가 전부 비어 있다.
-- 그 상태에서 선택기를 그리면 이름·직업·수치가 전부 null 로 나온다.
-- editDisplay 에서 심으면 표시 코드가 변수를 만들게 되므로 그쪽은 쓰지 않는다.
-- 대신 0번을 인트로로 두고, 사용자가 누르는 그 순간에 심는다.
--   setup_num = 0 : 인트로. 기본 변수로 박아두므로 LUA 없이도 뜬다
--   setup_num = 1 : 시나리오 선택기. 여기부터 변수가 채워져 있다
function startSetup(tid)
  initDefaults(tid)
  setChatVar(tid, "setup_num", "1")
  setChatVar(tid, "char_pop", "0")
  redraw(tid)
end

function goMain(tid)
  initDefaults(tid)
  setChatVar(tid, "setup_num", "1")
  redraw(tid)
end

-- 옛 목록 화면(여자냐 남편이냐만 묻던 뎁스)은 없앴다.
-- 여자 4명과 남편 4명을 선택기 한 화면에 부부 단위로 깐다.
-- 두 함수는 정규식과 편집 화면의 뒤로가기가 계속 부르므로 선택기(1번)로 보낸다.
function goWomanList(tid)   setChatVar(tid, "setup_num", "1"); redraw(tid) end
function goHusbandList(tid) setChatVar(tid, "setup_num", "1"); redraw(tid) end

-- 출연 여부와 무관하게 언제든 편집할 수 있다.
-- 출연 중 편집을 막아도 [출연 끄기 → 편집 → 다시 켜기] 로 같은 결과가 나온다.
-- 절차만 늘고 막히는 건 없으므로 잠그지 않는다. 서사와 어긋나게 바꾸는 것은 사용자 판단이다.
local function openWoman(tid, n)
  setChatVar(tid, "scen_sel", "0")   -- 손으로 고치기 시작하면 프리셋 표시를 뗀다
  setChatVar(tid, "edit_target", tostring(n))
  setChatVar(tid, "setup_num", "2")
  redraw(tid)
end
function editW1(tid) openWoman(tid, 1) end
function editW2(tid) openWoman(tid, 2) end
function editW3(tid) openWoman(tid, 3) end
function editW4(tid) openWoman(tid, 4) end

local function openHusband(tid, n)
  setChatVar(tid, "scen_sel", "0")
  setChatVar(tid, "edit_target", tostring(n))
  setChatVar(tid, "setup_num", "4")
  redraw(tid)
end
function editH1(tid) openHusband(tid, 1) end
function editH2(tid) openHusband(tid, 2) end
function editH3(tid) openHusband(tid, 3) end
function editH4(tid) openHusband(tid, 4) end

--------------------------------------------------
-- 여자 항목 편집
--------------------------------------------------
local function wp(tid) return "w"..gn(tid, "edit_target", 1).."_" end

function setWType(tid) openPicker(tid, "TYPES", wp(tid).."type", "성격 유형", 2, 1) end
function setWJob(tid)  openPicker(tid, "JOBS",  wp(tid).."job",  "직업",      2, 2) end
function setWRel(tid)  openPicker(tid, "RELS",  wp(tid).."rel",  "{{user}}와의 관계", 2, 2) end

-- 직접 입력 트리거를 찍어내는 공장.
-- 목록 번호 자리에 99 를 심고 실제 문자열은 <field>_txt 에 따로 보관한다.
-- 99 를 남겨두는 이유는 선택기 재진입 시 어느 칩이 켜져 있는지 표시하기 위해서다.
local function makeTextSetter(field, label)
  return async(function(tid)
    local v = alertInput(tid, label):await()
    if v and v ~= "" then
      setChatVar(tid, wp(tid)..field,          tostring(CUSTOM_IDX))
      setChatVar(tid, wp(tid)..field.."_txt",  v)
    end
    -- 인물 편집은 선택기 한 곳뿐이므로 언제나 그쪽으로 돌아간다.
    setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
    redraw(tid)
  end)
end

setWJobText = makeTextSetter("job", "직업을 직접 입력하세요")

-- 자녀 칩 전용 트리거.
-- 단계를 심고 곧바로 이름을 받는다.
--
-- applyPick 안에서 async 함수를 부르면 입력창은 뜨지만 그 뒤가 끊긴다.
-- RisuAI 는 트리거로 직접 불린 async 함수만 await 이후를 이어준다.
-- 그래서 칩 자체를 async 트리거로 만들고, 자녀 목록만 이 트리거를 쓰게 한다.
local function kidReturn(tid)
  setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
  redraw(tid)
end

for i = 1, 8 do
  _G["pickKid"..i] = async(function(tid)
    local wpre = "w"..gn(tid, "edit_target", 1).."_"
    setChatVar(tid, wpre.."kids", tostring(i))
    if i == 1 then
      setChatVar(tid, wpre.."kid_txt", "")        -- 없음이면 이름도 성별도 지운다
      setChatVar(tid, wpre.."kid_sex", "")
    else
      local v = alertInput(tid, "자녀 이름을 입력하세요 (성 제외)"):await()
      if v and v ~= "" then
        setChatVar(tid, wpre.."kid_txt", v)
      end
    end
    kidReturn(tid)
  end)
end

-- 축 수치 직접 입력. 단계 선택기 상단 배지가 부른다.
-- 단계 칩은 구간 중앙값(30·90·150·210·270)만 심을 수 있어 미세 조정이 안 된다.
-- 어느 축인지는 sel_key 로 안다. 축마다 트리거를 따로 두지 않는다.
local STAGE_FIELD = { __stageH = "aff", __stageL = "lewd", __stageG = "guilt", __stageS = "susp" }

setStageNum = async(function(tid)
  local field = STAGE_FIELD[gv(tid, "sel_key", "")]
  if not field then return end
  local v = alertInput(tid, "0 ~ 300 사이의 숫자를 입력하세요"):await()
  local n = tonumber(v)
  if n then
    n = math.floor(n)
    if n < 0   then n = 0   end
    if n > 300 then n = 300 end
    local t = gn(tid, "edit_target", 1)
    -- 의심만 저장 위치가 남편 슬롯이다. 여자 쪽에 쓰면 refreshLabels 가
    -- 남편 값으로 덮어써서 입력이 조용히 사라진다.
    if field == "susp" then
      setChatVar(tid, "h"..gn(tid, "w"..t.."_hus", t).."_susp", tostring(n))
    else
      setChatVar(tid, "w"..t.."_"..field, tostring(n))
    end
  end
  setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
  redraw(tid)
end)

-- 자녀 성별. 선택기 상단 탭이 부른다.
-- renderPicker 를 직접 불러야 선택된 쪽 강조가 즉시 바뀐다.
local function setKidSex(tid, v)
  setChatVar(tid, wp(tid).."kid_sex", v)
  refreshLabels(tid)
  if gv(tid, "sel_list", "") == "KIDS" then renderPicker(tid) end
  redraw(tid)
end

function setKidSexM(tid) setKidSex(tid, "M") end
function setKidSexF(tid) setKidSex(tid, "F") end

-- 단계는 그대로 두고 이름만 고칠 때 쓴다. 선택기 상단 배지가 부른다.
setWKidName = async(function(tid)
  local v = alertInput(tid, "자녀 이름을 입력하세요 (성 제외)"):await()
  if v and v ~= "" then
    setChatVar(tid, wp(tid).."kid_txt", v)
  end
  kidReturn(tid)
end)
setWRelText = makeTextSetter("rel", "관계를 직접 입력하세요")

-- 페티시와 성적 취향. 목록으로 감당이 안 되는 값이라 자유 입력이다.
-- 단계와 무관하게 상시로 프롬프트에 나간다. 채워 넣는 즉시 반영된다.
-- 빈 문자열은 alertInput 취소와 구분이 안 되므로 지우기는 별도 트리거로 뺐다.
-- 미혼으로 바꾸면 자녀를 비운다. 남편 슬롯 하나를 여러 여자가 참조할 수 있으므로
-- 그를 가리키는 여자를 전부 훑는다.
-- 값만 남겨두면 선택기에서는 안 보이는데 프로필에는 자녀가 찍혀 나간다.
local function clearKidsFor(tid, hn)
  for i = 1, 4 do
    if gn(tid, "w"..i.."_hus", i) == hn then
      setChatVar(tid, "w"..i.."_kids",    "1")
      setChatVar(tid, "w"..i.."_kid_txt", "")
      setChatVar(tid, "w"..i.."_kid_sex", "")
    end
  end
end

-- 관계 형태를 지정한다. 값은 남편 슬롯에 쓴다.
-- 여자 화면과 남편 화면이 같은 변수를 건드리므로 둘이 항상 같은 값을 본다.
-- 뒤집기가 아니라 지정이라 같은 칸을 두 번 눌러도 되돌아가지 않는다.
-- 사별을 붙일 때도 값 하나만 늘리면 된다.
local function setSingle(tid, hn, on)
  local cur = (gv(tid, "h"..hn.."_single", "0") == "1")
  if cur == on then return end
  setChatVar(tid, "h"..hn.."_single", on and "1" or "0")
  if on then clearKidsFor(tid, hn) end
  -- 대역이 갈리므로 나이를 새 대역 안으로 밀어넣는다.
  -- 다시 굴리지 않고 자르기만 한다. 이미 두 대역에 다 드는 나이면 그대로 남는다.
  local lo, hi = AGE_MIN, AGE_MAX
  if on then lo, hi = AGE_BF_MIN, AGE_BF_MAX end
  for k = 1, 4 do
    if gn(tid, "w"..k.."_hus", k) == hn then
      local wa = clampAge(gn(tid, "w"..k.."_age", 29), lo, hi)
      setChatVar(tid, "w"..k.."_age", tostring(wa))
      setChatVar(tid, "h"..hn.."_age", tostring(clampAge(gn(tid, "h"..hn.."_age", wa + 3), wa, wa + 8)))
    end
  end
  redraw(tid)
end

-- 여자 화면. 그 여자의 남편 슬롯을 고친다.
local function wHus(tid)
  return gn(tid, wp(tid).."hus", gn(tid, "edit_target", 1))
end

function setWWed(tid) setSingle(tid, wHus(tid), false) end
function setWBf (tid) setSingle(tid, wHus(tid), true)  end

