  if v ~= nil then
    v = tostring(v):gsub("^%s+", ""):gsub("%s+$", "")
    if v ~= "" then setChatVar(tid, wp(tid).."pref", v) end
  end
  redraw(tid)
end)

function clearWPref(tid)
  setChatVar(tid, wp(tid).."pref", "")
  redraw(tid)
end

-- 후보 목록에서 하나를 다시 뽑는다.
-- 선택기를 열어 고르는 것과 결과는 같고, 손이 한 번 덜 간다.
-- 지금 값과 같은 것이 나오면 한 번 더 굴린다. 눌렀는데 아무 일도 안 일어난 것처럼
-- 보이면 버튼이 고장 난 것으로 읽힌다.
local function rollInto(tid, field, pool)
  local k   = wp(tid)..field
  local now = gv(tid, k, "")
  local v   = pickOne(pool)
  if v == now and #pool > 1 then v = pickOne(pool) end
  setChatVar(tid, k, v)
  if gv(tid, "sel_list", "") == ((field == "fetish") and "FETISH" or "PREF") then
    renderPicker(tid)
  end
  redraw(tid)
end

function rollWFetish(tid) rollInto(tid, "fetish", FETISH_POOL) end
function rollWPref(tid)   rollInto(tid, "pref",   PREF_POOL)   end

-- 목록에서 고르는 화면. 상단에 직접 입력 · 다시 뽑기 · 비우기가 함께 붙는다.
