setWCodeText = async(function(tid)
  local v = alertInput(tid, "에셋 번호를 입력하세요 (1 ~ "..FNPC_MAX..")"):await()
  local n = tonumber(v)
  if n then
    n = math.floor(n)
    if n < 1 then n = 1 end
