      alertError(tid, "이미 다른 슬롯이 쓰고 있는 에셋입니다")
      return
    end
    setChatVar(tid, wp(tid).."code", tostring(n))
    setChatVar(tid, "setup_num", gv(tid, "sel_back", "1"))
  end
  redraw(tid)
end)

