-- 유형 추천 조합 적용. 현재 유형에 맞춰 여자·남편 필드를 한 번에 채운다.
-- 아내와 {{user}}의 관계가 남편과 {{user}}의 관계를 제약한다.
-- 아내가 "상사의 아내" 면 남편은 {{user}}의 상사여야 한다. 이런 것들이다.
-- 이 표를 안 두면 「아내는 내 직장 상사인데 남편은 나를 전혀 모른다」가 나온다.
-- 값은 H_USER 인덱스다.
local H_USER_OK = {
  -- 처가·인척 : 여자가 인척이면 남편도 인척이다. 호칭이 정해져 있다.
  [1]={24,12,11},             -- 처제      → 남편이 동서
  [2]={24,12,11},             -- 처형      → 남편이 동서
  [3]={21},                   -- 형수      → 남편이 {{user}} 의 형
  [4]={22},                   -- 제수      → 남편이 {{user}} 의 남동생
  [5]={23},                   -- 사촌 형수·제수 → 남편이 사촌 형·남동생
  [6]={25},                   -- 장모      → 남편이 장인
  [7]={12,11,13},             -- 아내의 사촌 → 그 남편은 딱 떨어지는 호칭이 없다
  [8]={26},                   -- 겹사돈    → 사돈
  -- 친구·지인 : 남편이 곧 {{user}}의 지인인 경우가 있다
  [9]={11,13,16,12},          -- 아내 친구
  [10]={1,8,2,3},             -- 친구 아내  → 남편이 친구
  [11]={2},                   -- 선배 아내  → 남편이 선배
  [12]={3},                   -- 후배 아내  → 남편이 후배
  [13]={13,16,11},            -- 동창
  [14]={13,16,14,19},         -- 첫사랑
  [15]={13,16,14,19},         -- 옛 연인
  [16]={13,16,11},            -- 아내의 직장 동료
  -- 직장·업무
  [17]={13,16,17}, [18]={13,16,17}, [19]={13,16,17},
  [20]={7,16,13},             -- 거래처 담당자
  [21]={4},                   -- 상사의 아내 → 남편이 직장 상사
  [22]={5},                   -- 부하의 아내 → 남편이 직장 부하
  -- 이웃·생활권 : 같은 동네면 남편도 눈에 띈다
  [23]={9,17,16}, [24]={9,17,16}, [25]={9,17,16}, [26]={9,17,16}, [27]={9,17,16},
  -- 서비스
  [28]={16,17,13}, [29]={16,17,13},
  -- 학교·육아
  [30]={9,16,17}, [31]={16,13}, [32]={16,13},
  -- 커뮤니티
  [33]={16,17,1}, [34]={16,17,1}, [35]={16,17,1},
  -- 우연·기타
  [36]={16,14,15}, [37]={16,14,15},
  [38]={16,18,19},            -- 사고·사건으로 얽힌 사이
  [39]={20,16},               -- 은인
  [40]={16},                  -- 완전한 타인
}

-- 아내 직업이 남편 직업을 규정하는 경우.
-- 의사 아내인데 남편이 무직이면 모순이다. JOBS → H_JOB 인덱스.
local H_JOB_FIXED = {
  [36] = 27,   -- 재벌가 며느리  → 재벌 2세
  [37] = 21,   -- 국회의원 아내  → 국회의원·정치인
  [38] =  9,   -- 의사 아내      → 의사
  [39] = 17,   -- 군장교 아내    → 군인·장교
}

-- 남편 추천 조합.
-- 남편만 따로 굴리면 모순이 나온다.
--   애처가 + 폭력·외도 / 신혼인데 자녀가 중고생 / 불임인데 자녀가 있음
--   정략결혼한 무직 / 아내의 직장 상사이면서 남편의 부하
-- 관계 9 x 결함 9 x 부재 6 x 직업 30 x {{user}}관계 20 = 29만 조합인데
-- 말이 되는 것은 일부다.
--
-- TYPE_PRESET 의 후보 150개는 이미 아내 유형에 맞춰 검수된 조합이라,
-- 아내를 기준으로 뽑으면 무작위이면서도 모순이 없다.
-- 이름과 아내 지정은 건드리지 않는다. 그 둘은 위에서 정하고 여기서 나머지를 채운다.
function applyHPreset(tid)
  local hn = gn(tid, "edit_target", 1)

  -- 이 남편을 참조하는 아내를 찾는다. 없으면 슬롯 번호가 같은 여자를 쓴다.
  local wn = nil
  for i = 1, 4 do
    if gn(tid, "w"..i.."_hus", i) == hn then wn = i break end
  end
  wn = wn or hn

  local lst = TYPE_PRESET[gn(tid, "w"..wn.."_type", 1)]
  if not lst or #lst == 0 then return end

  -- 아내에게 자녀가 있으면 신혼(hA=3)·불임(hB=8) 후보를 뺀다.
  local kids = gn(tid, "w"..wn.."_kids", 1)
  local pool = {}
  for _, pz in ipairs(lst) do
    if not (kids > 2 and (pz.hA == 3 or pz.hB == 8)) then pool[#pool+1] = pz end
  end
  if #pool == 0 then pool = lst end

  local pz = pool[math.random(#pool)]

  -- {{user}}와의 관계는 아내 쪽 관계가 정한다. 후보 값이 어긋나면 갈아끼운다.
  local hUser = pz.hUser
  local ok = H_USER_OK[gn(tid, "w"..wn.."_rel", 1)]
  if ok then
    local hit = false
    for _, v in ipairs(ok) do if v == hUser then hit = true break end end
    if not hit then hUser = ok[math.random(#ok)] end
  end

  -- 아내 직업이 남편을 규정하면 그쪽을 따른다. 직접 입력(99)이면 표에 없으므로 후보 값을 쓴다.
  local hJob = H_JOB_FIXED[gn(tid, "w"..wn.."_job", 1)] or pz.hJob

  local h = "h"..hn.."_"
  setChatVar(tid, h.."relA", tostring(pz.hA))
  setChatVar(tid, h.."relB", tostring(pz.hB))
  setChatVar(tid, h.."relC", tostring(pz.hC))
  setChatVar(tid, h.."job",  tostring(hJob))
  setChatVar(tid, h.."user", tostring(hUser))
  -- 아내 나이는 그대로 두고 남자 쪽만 다시 굴린다. 여기서 바뀌는 것은 남자뿐이다.
  setChatVar(tid, h.."age",  tostring(rndHAge(gn(tid, "w"..wn.."_age", 29))))
  setChatVar(tid, "scen_sel", "0")
  redraw(tid)
end

-- 유형별 후보 10개 중 하나를 무작위로 뽑아 채운다.
-- 같은 유형을 여러 번 눌러도 매번 다른 조합이 나오되, 전부 검수된 조합이다.
-- 이름과 유형은 건드리지 않는다. 유형을 읽어서 나머지를 채우는 것이므로
-- 유형을 먼저 정하고 눌러야 한다.
function applyPreset(tid)
  local wn  = gn(tid, "edit_target", 1)
  local w   = "w"..wn.."_"
  local lst = TYPE_PRESET[gn(tid, w.."type", 1)]
  if not lst or #lst == 0 then return end
  local pz = lst[math.random(#lst)]

  setChatVar(tid, w.."job",   tostring(pz.job))
  setChatVar(tid, w.."rel",   tostring(pz.rel))
  setChatVar(tid, w.."kids",  tostring(pz.kids))
  setChatVar(tid, w.."kid_sex", pz.sex)
  setChatVar(tid, w.."kid_txt", KID_NAME[pz.sex] or "")
  setChatVar(tid, w.."aff",   tostring(pz.aff))
  setChatVar(tid, w.."lewd",  tostring(pz.lewd))
  setChatVar(tid, w.."guilt", tostring(pz.guilt))
  setChatVar(tid, w.."affair", "0")
  -- 페티시·성적 취향도 함께 다시 뽑는다. 이 버튼은 인물을 통째로 새로 굴리는 자리라
  -- 직업과 관계가 갈렸는데 이 두 칸만 옛 인물의 것으로 남으면 어긋난다.
  setChatVar(tid, w.."fetish", pickOne(FETISH_POOL))
  setChatVar(tid, w.."pref",   pickOne(PREF_POOL))
  -- 나이. 자녀 단계가 통째로 갈리므로 함께 다시 굴린다.
  local wAge = rndAge(pz.kids, wIsBf(tid, wn))
  setChatVar(tid, w.."age", tostring(wAge))

  -- 참조 중인 남편 슬롯도 함께 채운다
  local h = "h"..gn(tid, w.."hus", 1).."_"
  setChatVar(tid, h.."age",  tostring(rndHAge(wAge)))
  setChatVar(tid, h.."relA", tostring(pz.hA))
  setChatVar(tid, h.."relB", tostring(pz.hB))
  setChatVar(tid, h.."relC", tostring(pz.hC))
  setChatVar(tid, h.."job",  tostring(pz.hJob))
  setChatVar(tid, h.."user", tostring(pz.hUser))

  redraw(tid)
end

-- 남편 자동 매칭 옵션. 켜면 여자N이 남편N을 자동으로 참조한다.
-- 뒤집기가 아니라 지정이라, 이미 켜진 칸을 다시 눌러도 값이 안 바뀐다.
local function setHusAutoTo(tid, on)
  if (gv(tid, "hus_auto", "1") == "1") == on then return end
  setChatVar(tid, "hus_auto", on and "1" or "0")
  refreshLabels(tid)
  -- 남편 선택 화면에 떠 있으면 상단 탭과 목록을 즉시 갱신한다.
  -- redraw 만으로는 sel_tabs / sel_html 이 다시 만들어지지 않는다.
  if gv(tid, "sel_list", "") == "HUS" then renderPicker(tid) end
  redraw(tid)
end

function setHusAuto(tid)   setHusAutoTo(tid, true)  end
function setHusManual(tid) setHusAutoTo(tid, false) end

-- 남편 슬롯에서 아내를 지정한다.
-- 자동 모드였다면 수동으로 전환한다. (자동은 매 턴 슬롯 번호로 덮어쓰므로)
