local function flipScene(tid, n)
  local k = "w"..n.."_scene"
  setChatVar(tid, k, (gv(tid, k, "0") == "1") and "0" or "1")
  redraw(tid)
end
function scene1(tid) flipScene(tid, 1) end
function scene2(tid) flipScene(tid, 2) end
function scene3(tid) flipScene(tid, 3) end
function scene4(tid) flipScene(tid, 4) end

-- 전체 해제 / 전체 선택
function sceneClear(tid)
  for i = 1, 4 do setChatVar(tid, "w"..i.."_scene", "0") end
  redraw(tid)
end

function sceneAll(tid)
  for i = 1, 4 do setChatVar(tid, "w"..i.."_scene", "1") end
  redraw(tid)
end

-- {{user}}와 불륜유무 진행 여부 토글
