--------------------------------------------------
-- AI 태그로 상태 수치 갱신
--------------------------------------------------
-- [msj_aff::±N::사유]    호감  0~300
-- [msj_lewd::±N::사유]   음란  0~300
-- [msj_guilt::±N::사유]  죄책  0~300 (클수록 죄책감이 강하다)
-- [msj_susp::±N::사유]   의심  0~300 (남편의 것. h{n}_susp 에 쌓인다)
--
-- 대상은 항상 현재 활성 캐릭터(active_w)다.
-- 턴당 변동 상한은 두지 않는다. AI 가 판정한 폭을 그대로 반영한다.
-- 유일한 경계는 축 자체의 0~300 범위뿐이다.

-- 변동 배수. 축마다 "플레이어가 빨라지길 바라는 방향"에만 곱한다.
--   호감·음란 : 증가에만. 배수를 올리는 사람은 빨리 오르게 하려는 것이지
--               빨리 떨어지게 하려는 게 아니다.
--   죄책      : 감소에만. 값이 클수록 죄책감이 강한 반전 축이라
--               빨리 풀리기를 바라는 것이지 빨리 쌓이기를 바라는 게 아니다.
-- bump(실제 반영)와 editDisplay(카드 표시)가 이 함수를 공유하므로
-- 화면 숫자와 실제 반영값이 갈라지지 않는다.
local MULT_KEY = { aff = "msj_mult_aff", lewd = "msj_mult_lewd", guilt = "msj_mult_guilt", susp = "msj_mult_susp" }

local function applyMult(tid, key, delta, slot)
  local k = MULT_KEY[key]
  if not k then return delta end
  if key == "guilt" then
    if delta >= 0 then return delta end     -- 죄책 증가는 그대로
  else
    if delta <= 0 then return delta end     -- 호감·음란·의심 감소는 그대로
  end
  local m = tonumber(getChatVar(tid, k) or "") or 1
  -- 의심은 성향·부재 배수가 한 번 더 곱해진다. 카드에는 사용자 설정값만 표시되고
  -- 이쪽은 숨겨진다. 남편이 어떤 사람인지가 화면 숫자로 새어나가지 않게 한다.
  if key == "susp" and slot then m = m * suspMult(tid, slot) end
  if m == 1 then return delta end
  local r
  if delta < 0 then r = -math.floor(-delta * m + 0.5) else r = math.floor(delta * m + 0.5) end
  -- 0.25 배수에서 ±1 같은 작은 변동이 0으로 반올림돼 조용히 사라지는 것을 막는다.
  -- 느리게 가자는 뜻이지 없던 일로 하자는 뜻이 아니다.
  if r == 0 then r = (delta > 0) and 1 or -1 end
  return r
end

-- 태그의 대상 식별자를 슬롯 번호로 바꾼다.
--   1순위 : 슬롯 ID   Female1 / female2 / F3 / 3
--   2순위 : 등록된 이름 (AI가 실명으로 쓴 경우 대비)
--   실패  : 주 대상
local function slotByName(tid, nm)
  if nm and nm ~= "" then
    nm = nm:match("^%s*(.-)%s*$")
    local n = nm:match("^[Ff]emale%s*(%d)$") or nm:match("^[Ff]%s*(%d)$") or nm:match("^(%d)$")
    n = tonumber(n)
    if n and n >= 1 and n <= 4 then return n end
    for i = 1, 4 do
      if gv(tid, "w"..i.."_name", "") == nm then return i end
    end
  end
  return gn(tid, "active_w", 1)
end

local function bump(tid, key, delta, nm)
  if delta == 0 then return end   -- 0 태그는 여기서 버린다. 프롬프트로 막지 않아도 된다
  local a = slotByName(tid, nm)
  -- 무대에 누가 서는가는 사용자만 정한다. 태그는 그 판을 못 바꾼다.
  -- 예전에는 꺼진 슬롯 앞으로 태그가 오면 그 슬롯을 켰고, 세 갈래로 샜다.
  --   1. 모델이 언급만 한 인물이 무대에 올라온다
  --   2. 자녀·남편 이름은 slotByName 이 못 맞춰 active_w 로 떨어지는데,
  --      아무도 안 켜져 있으면 active_w 는 1 로 고정된다(initDefaults).
  --      전체 해제 직후 태그 하나에 w1 이 되살아났다
  --   3. 자녀 풀네임(아빠 성 + 이름)이 다른 슬롯의 여자 이름과 같으면
  --      그 슬롯이 켜졌다
  -- 이제 꺼진 슬롯 앞으로 온 태그는 통째로 버린다. 켜지도 않고 쌓지도 않는다.
  -- 꺼진 인물은 OOC 에도 실리지 않으므로 그 태그는 애초에 근거가 없다.
  -- 전원 꺼짐도 같은 규칙에 함께 걸린다. 어느 슬롯으로 떨어지든 꺼져 있다.
  if gv(tid, "w"..a.."_scene", "0") ~= "1" then return end
  delta = applyMult(tid, key, delta, a)
  if delta == 0 then return end
  -- 의심만 저장 위치가 다르다. 태그는 여자 ID 로 오지만 값은 남편의 것이다.
  -- w{a}_hus 가 가리키는 남편 슬롯을 찾아 거기에 쌓는다. 일부일처라 섞이지 않는다.
  local k
  if key == "susp" then
    k = "h"..gn(tid, "w"..a.."_hus", a).."_susp"
  else
    k = "w"..a.."_"..key
  end
  local v = gn(tid, k, 0) + delta
  if v < 0   then v = 0   end
  if v > 300 then v = 300 end
  setChatVar(tid, k, tostring(v))
end

function parseStatTags(tid, content)
  if not content or content == "" then return end
  -- 이름 지정형 [msj_aff::이름::±N::사유]
  for nm, v in content:gmatch("%[msj_aff::([^:%]]+)::([%+%-]?%d+)::[^%]]*%]")   do bump(tid, "aff",   tonumber(v) or 0, nm) end
  for nm, v in content:gmatch("%[msj_lewd::([^:%]]+)::([%+%-]?%d+)::[^%]]*%]")  do bump(tid, "lewd",  tonumber(v) or 0, nm) end
  for nm, v in content:gmatch("%[msj_guilt::([^:%]]+)::([%+%-]?%d+)::[^%]]*%]") do bump(tid, "guilt", tonumber(v) or 0, nm) end
  for nm, v in content:gmatch("%[msj_susp::([^:%]]+)::([%+%-]?%d+)::[^%]]*%]")  do bump(tid, "susp",  tonumber(v) or 0, nm) end
  -- 이름 생략형 [msj_aff::±N::사유] → 주 대상
  for v in content:gmatch("%[msj_aff::([%+%-]?%d+)::[^%]]*%]")   do bump(tid, "aff",   tonumber(v) or 0) end
  for v in content:gmatch("%[msj_lewd::([%+%-]?%d+)::[^%]]*%]")  do bump(tid, "lewd",  tonumber(v) or 0) end
  for v in content:gmatch("%[msj_guilt::([%+%-]?%d+)::[^%]]*%]") do bump(tid, "guilt", tonumber(v) or 0) end
  for v in content:gmatch("%[msj_susp::([%+%-]?%d+)::[^%]]*%]")  do bump(tid, "susp",  tonumber(v) or 0) end
  refreshLabels(tid)
end

--------------------------------------------------
-- [리롤 롤백] 누적 수치 이중 적용 방지
--------------------------------------------------
-- 리롤은 마지막 AI 메시지를 갈아끼우는 동작이라 메시지 개수가 그대로다.
-- 그래서 onOutput 이 같은 턴에서 한 번 더 돌고, bump() 가 더한 값이 또 더해진다.
--   호감 30 → 응답 A(+5) → 35 → 리롤 → 응답 B(+4) → 39
-- 39가 아니라 34가 맞다. 응답 A 는 버려진 응답이다.
--
-- 방식은 적용 '직전' 상태를 스냅샷 하나에 담아두는 것이다.
--   새 턴  : 스냅샷을 갱신하고 그대로 진행
--   같은 턴: 리롤이므로 스냅샷으로 되돌린 뒤 새 응답을 적용
-- 스냅샷은 리롤 때 지우지 않는다. 연속으로 굴려도 매번 같은 지점에서 시작해야 한다.
--
-- 덮어쓰기 값(날짜·시각·장소)은 몇 번을 다시 써도 마지막 값만 남으므로 대상이 아니다.
-- 대상은 bump() 를 타는 누적 값 넷뿐이다.
-- 출연 플래그(w{i}_scene)는 뺐다. 예전에는 태그가 그걸 켰기 때문에 되돌릴
-- 이유가 있었지만, 이제 출연은 사용자만 건드린다. 그대로 두면 원본 응답과
-- 리롤 사이에 사용자가 손으로 켠 인물이 리롤 때 도로 꺼진다.
local RB_KEYS
local function rbKeys()
  if RB_KEYS then return RB_KEYS end
  RB_KEYS = {}
  for i = 1, 4 do
    RB_KEYS[#RB_KEYS+1] = "w"..i.."_aff"
    RB_KEYS[#RB_KEYS+1] = "w"..i.."_lewd"
    RB_KEYS[#RB_KEYS+1] = "w"..i.."_guilt"
    RB_KEYS[#RB_KEYS+1] = "h"..i.."_susp"
  end
  return RB_KEYS
end

-- 형식 : T=<턴>;<키>=<값>;<키>=<값>;...
-- 값이 전부 숫자라 구분자(; =)와 부딪히지 않는다. json 을 쓸 이유가 없다.
local function rbSave(tid, turnNo)
  local parts = { "T="..turnNo }
  for _, k in ipairs(rbKeys()) do parts[#parts+1] = k.."="..gv(tid, k, "0") end
  setChatVar(tid, "msj_rb", table.concat(parts, ";"))
end

local function rbIsReroll(tid, turnNo)
  local raw = gv(tid, "msj_rb", "")
  if raw == "" then return false end
  local t = raw:match("^T=(%d+)")
  return t ~= nil and tonumber(t) == turnNo
end

local function rbRestore(tid)
  local raw = gv(tid, "msj_rb", "")
  if raw == "" then return end
  for k, v in raw:gmatch("([^;=]+)=([^;]+)") do
    if k ~= "T" then setChatVar(tid, k, v) end
  end
end

-- onOutput 진입 직후에 부른다. 이 호출 뒤의 태그 적용은 항상 '적용 전 상태' 위에서 이뤄진다.
local function rbBeginTurn(tid, turnNo)
  if rbIsReroll(tid, turnNo) then rbRestore(tid) else rbSave(tid, turnNo) end
end

-- OOC 블록 제거. 지우는 자리가 네 군데(onStart · onOutput · editRequest · editDisplay)라
-- 패턴을 한 곳에 둔다. 한 군데만 고치고 나머지를 놓치는 일이 실제로 있었다.
--
-- 두 번째 gsub 는 END 마커가 유실된 블록을 위한 것이다.
-- 첫 패턴은 START 와 END 가 짝을 이룰 때만 걸리므로, 생성이 중간에 끊기거나
-- 마커 한 줄이 깨지면 블록 전체가 화면과 컨텍스트에 그대로 남는다.
-- 블록은 항상 메시지 맨 뒤에 붙으니 START 부터 끝까지 잘라내도 본문은 상하지 않는다.
local function stripOoc(s)
  if not s then return s end
  s = s:gsub("%s*%[MSJ_PROMPT_START%].-%[MSJ_PROMPT_END%]", "")
  if s:find("[MSJ_PROMPT_START]", 1, true) then
    s = s:gsub("%s*%[MSJ_PROMPT_START%].*$", "")
  end
  return s
end

-- OOC 로그 보존 개수. 최근 N개 유저 메시지의 OOC 블록만 채팅 데이터에 남기고
-- 그 이전은 지운다.
-- editRequest 가 어차피 AI 컨텍스트에서는 매번 걷어내므로, 이 값이 정하는 것은
-- '메시지 수정 화면을 열었을 때 원문이 보이는가' 와 저장 용량뿐이다.
--   0  전부 즉시 삭제 (배포용)
--   N  최근 N개는 남긴다 (디버그용. OOC 가 실제로 뭘 내보냈는지 확인할 때)
local OOC_KEEP = 0

-- 오래된 OOC 블록 정리. 최근 OOC_KEEP 개만 남긴다.
local function pruneOocLogs(tid, chatLen)
  local seen = 0
  for i = chatLen - 1, 0, -1 do
    local m = getChat(tid, i)
    if m and m.role == "user" and m.data
       and m.data:find("[MSJ_PROMPT_START]", 1, true) then
      seen = seen + 1
      if seen > OOC_KEEP then
        setChat(tid, i, stripOoc(m.data))
      end
    end
  end
end

onOutput = function(tid)
  local chatLen = getChatLength(tid) or 0
  if chatLen < 1 then return end

  -- 오래된 OOC 블록부터 걷어낸다. 채팅 데이터에 계속 쌓일 이유가 없다.
  pruneOocLogs(tid, chatLen)

  -- 리롤이면 직전 적용분을 되돌린다. 태그를 읽기 전에 해야 한다.
  -- 턴 번호로 메시지 개수를 쓴다. 리롤은 마지막 메시지를 갈아끼우므로 개수가 그대로고,
  -- 새 턴은 유저+AI 두 개가 늘어 반드시 달라진다.
  rbBeginTurn(tid, chatLen)

  -- 마지막 char(AI) 메시지를 찾는다
  for i = chatLen - 1, 0, -1 do
    local m = getChat(tid, i)
    if m and m.role == "char" then
      if m.data then
        -- 혹시 응답에 OOC 블록이 섞여 들어왔으면 걷어낸 뒤 읽는다.
        -- 블록 안에는 태그 예시가 들어 있어 그대로 파싱하면 예시가 수치로 반영된다.
        local body = stripOoc(m.data)
        parseStatTags(tid, body)
        parseStatusTag(tid, body)
      end
      break
    end
  end
end

