-- [STW] 상태창 (날짜 / 시각 / 장소)
--------------------------------------------------
-- AI가 매 턴 [MSJ_STATUS::날짜::시각::장소] 를 응답 끝에 붙인다.
-- onOutput 이 파싱해 변수에 저장하고, editDisplay 가 상태창으로 렌더한다.

local MSJ_STW_CSS = [[<style>.msj-stw{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:linear-gradient(135deg,#141418 0%,#1a1a20 100%);border:1px solid #2e2e34;border-radius:8px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;margin:8px 0;gap:8px;box-sizing:border-box;max-width:100%;flex-wrap:wrap;}.msj-stw-l{display:flex;align-items:center;gap:6px;min-width:0;flex-wrap:wrap;}.msj-stw-r{display:flex;align-items:center;gap:6px;min-width:0;}.msj-stw-date{font-size:13px;color:#8a8a94;font-weight:500;letter-spacing:0.3px;white-space:nowrap;}.msj-stw-hour{font-size:14px;color:#e8e8ec;font-weight:700;letter-spacing:0.5px;white-space:nowrap;}.msj-stw-place{font-size:13px;color:#b0b0ba;font-weight:500;word-break:keep-all;overflow-wrap:anywhere;}@media(max-width:600px){.msj-stw{flex-direction:column;align-items:flex-start;gap:3px;padding:8px 12px;}.msj-stw-date{font-size:12px;}.msj-stw-hour{font-size:13px;}.msj-stw-place{font-size:12px;}}</style>]]

-- [MSJ_STATUS::날짜::시각::장소] 파싱. 여러 개면 마지막 것을 채택한다.
function parseStatusTag(tid, content)
  if not content or content == "" then return end
  local last
  for m in content:gmatch("%[MSJ_STATUS::(.-)%]") do last = m end
  if not last then return end

  local f = {}
  for part in (last.."::"):gmatch("(.-)::") do f[#f+1] = part:match("^%s*(.-)%s*$") end

  if f[1] and f[1] ~= "" and f[1]:upper() ~= "DATE" then setChatVar(tid, "st_date",  f[1]) end
  if f[2] and f[2] ~= "" and f[2]:upper() ~= "TIME" then setChatVar(tid, "st_time",  f[2]) end
  if f[3] and f[3] ~= "" and f[3]:upper() ~= "PLACE" and f[3] ~= "장소" then
    setChatVar(tid, "st_place", f[3])
  end

end

