-- NSFW 표기는 카드 설정이 정한다.
--
-- 모듈 커스텀 토글로 판정하려 했으나 RisuAI 가 토글 값을 세션에 캐시해
-- 바꿔도 채팅방을 나갔다 와야 반영됐다. 설정을 바꿨는데 화면이 그대로면
-- 사용자는 고장으로 읽는다. 그래서 확장팩은 붙어 있다고 전제하고,
-- 표기 여부만 카드에서 즉시 반응하는 칩으로 고른다.
--
-- 확장팩이 없으면 NSFW 자산 자체가 없어서 어차피 나올 것이 없다.
-- 감지해서 막을 이유가 크지 않았다.

-- 옵션 기본값. 값이 없으면 여기 값으로 읽는다.
local SET_DEF = {
  msj_mult_aff   = "1",     -- 호감 증가 배수
  msj_mult_lewd  = "1",     -- 음란 증가 배수
  msj_mult_guilt = "1",     -- 죄책 감소 배수
  -- 의심만 빠져 있었다. SET_DEF 에 없으면 setOpt 가 빈 문자열을 돌려주고,
  -- 칩은 cur 와 val 을 비교하므로 어느 칸도 켜지지 않는다.
  msj_mult_susp  = "1",     -- 의심 증가 배수
  msj_nsfw       = "1",     -- NSFW 스프라이트. 0 이면 화면에서 지운다 (지문 수위와 무관)
  -- 아래 셋은 전부 대화 중 스프라이트에만 걸린다. 캐릭터 설정 카드와는 무관하다.
  msj_img        = "big",   -- 스프라이트 크기. basic(320x468) / big(457x670)
  msj_tap        = "on",    -- 모바일. on = 탭 확대 / off = 처음부터 전체
  msj_dcfold     = "0",     -- 변동 카드. 0 = 펴기(사유 보임) / 1 = 접기(요약 한 줄)
}

function setOpt(tid, k)
  local v = getChatVar(tid, k)
  if v == nil or v == "" or v == "null" then return SET_DEF[k] or "" end
  return v
end

function setOptNum(tid, k)
  return tonumber(setOpt(tid, k)) or tonumber(SET_DEF[k]) or 0
end

-- 칩 한 개. cur 와 val 이 같으면 켜진 상태로 그린다.
local function chip(cur, val, fn, label)
  return '<span class="msj-chip' .. ((cur == val) and " on" or "") .. '" risu-trigger="' .. fn .. '">' .. label .. '</span>'
end

-- 동작 칩. 토글이 아니라 실행이므로 선택 강조를 쓰지 않는다.
local function actChip(fn, label)
  return '<span class="msj-chip act" risu-trigger="' .. fn .. '">' .. label .. '</span>'
end

local function item(label, chips)
  return '<div class="msj-item"><div class="msj-ilabel">' .. label .. '</div>'
      .. '<div class="msj-chips">' .. chips .. '</div></div>'
end

local function box(title, inner)
  return '<div class="msj-box"><div class="msj-btitle">' .. title .. '</div>' .. inner .. '</div>'
end

local function onoff(cur, fnOn, fnOff)
  return chip(cur, "1", fnOn, "표시") .. chip(cur, "0", fnOff, "숨김")
end

-- 인물 카드 한 장의 축 한 줄
local function pcRow(label, val, tier, color)
  local pct = math.floor((tonumber(val) or 0) / 300 * 100 + 0.5)
  if pct > 100 then pct = 100 end
  if pct < 0   then pct = 0   end
  return '<div class="msj-pc-rw">'
      .. '<span class="msj-pc-lb" style="color:' .. color .. ';">' .. label .. '</span>'
      .. '<span class="msj-pc-tg">(' .. tier .. ')</span>'
      .. '<span class="msj-pc-vl">' .. val .. '</span></div>'
      .. '<div class="msj-pc-bar"><i style="width:' .. pct .. '%;background:' .. color .. ';"></i></div>'
end

--------------------------------------------------
-- [SAVE] 세이브 코드 (채팅방 이사)
--------------------------------------------------
-- 대화가 길어져 새 방으로 옮길 때, 진행 상태를 문자열 하나로 옮긴다.
-- 승인연애의 세이브 코드와 같은 구조다.
--
-- 저장하는 것은 「사람이 정한 값」뿐이다. _kr 라벨, H/L/G/S 단계,
-- 여자 쪽 의심 미러, 상태 문구는 전부 refreshLabels 가 다시 만든다.
-- 그것까지 코드에 넣으면 길이만 늘고, 규칙이 바뀐 판에서 옛 문구가 되살아난다.
--
-- 화면 상태(edit_target · sel_* · char_pop · set_open)와 리롤 스냅샷(msj_rb)도 뺀다.
-- 옛 방의 턴 번호가 박혀 있어 새 방에서는 오히려 해롭다.
--
-- 버전은 올리지 않는다. v106 에서 pref 한 칸이 늘었지만, 형식이 키=값 쌍이고
-- 모르는 키는 허용 목록에서 걸러지므로 옛 코드도 그대로 읽힌다.
-- 버전을 올리면 이미 뽑아둔 코드가 전부 거부당한다. 얻는 것보다 잃는 게 크다.
local MSJ_SAVE_VER = "1"

-- 여자 슬롯의 소스 필드. 나머지는 전부 여기서 파생된다.
local SV_W = { "name","age","type","job","job_txt","rel","rel_txt",
               "kids","kid_sex","kid_txt","aff","lewd","guilt",
               "affair","scene","fetish","pref","hus","code" }

-- 남편 슬롯. 의심 수치는 남편이 들고 있으므로 이쪽에 있다.
local SV_H = { "name","age","relA","relA_txt","relB","relB_txt",
               "relC","relC_txt","job","job_txt","user","user_txt",
               "susp","single","code" }

-- 전역. 환경세팅 값도 함께 옮긴다. 배수를 다시 맞추게 하면 이사한 의미가 없다.
local SV_G = { "st_date","st_time","st_place","hus_auto","scen_sel",
               "msj_mult_aff","msj_mult_lewd","msj_mult_guilt","msj_mult_susp",
               "msj_img","msj_nsfw","msj_tap","msj_dcfold" }

-- 구분자(; =)와 HTML/CBS 위험문자({ } < > & ")를 ~X 두 글자로 바꾼다.
-- 값 안에 ; 와 = 가 남지 않으므로 파싱이 단순하고, { < & 가 없으니
-- 코드를 설정창 HTML 에 그대로 박아도 CBS 나 태그로 오인되지 않는다.
local SV_ENC = { ["~"]="~t", [";"]="~s", ["="]="~e", ["\n"]="~n", ["\r"]="",
                 ["{"]="~o", ["}"]="~c", ["<"]="~l", [">"]="~g", ["&"]="~a", ['"']="~q" }
local SV_DEC = { t="~", s=";", e="=", n="\n", o="{", c="}", l="<", g=">", a="&", q='"' }

local function svEnc(v) return (tostring(v or ""):gsub("[~;=\n\r{}<>&\"]", SV_ENC)) end
local function svDec(v) return (tostring(v or ""):gsub("~(.)", function(c) return SV_DEC[c] or "" end)) end

local function svKeys()
  local out = {}
  for i = 1, 4 do
    for _, f in ipairs(SV_W) do out[#out+1] = "w"..i.."_"..f end
    for _, f in ipairs(SV_H) do out[#out+1] = "h"..i.."_"..f end
  end
  for _, k in ipairs(SV_G) do out[#out+1] = k end
  return out
end

-- 빈 값은 코드에 넣지 않는다. 불러올 때 전 항목을 먼저 비우므로 결과가 같고,
-- _txt 계열이 대부분 비어 있어 길이가 절반 아래로 떨어진다.
-- gv 가 빈 문자열을 「없음」으로 보고 기본값을 돌려주므로 비워도 안전하다.
local function buildSaveCode(tid)
  local parts = { "MSJ"..MSJ_SAVE_VER }
  for _, k in ipairs(svKeys()) do
    local v = getChatVar(tid, k)
    if v ~= nil and v ~= "" and v ~= "null" then
      parts[#parts+1] = k.."="..svEnc(v)
    end
  end
  return table.concat(parts, ";")
end

-- 성공하면 복원 개수, 실패하면 nil 과 사유를 돌려준다.
local function applySaveCode(tid, raw)
  if type(raw) ~= "string" then return nil, "코드가 비었습니다." end
  -- 줄바꿈·탭 제거 + 앞뒤 공백 정리. RisuAI 가 붙이는 U+00A0 도 함께 턴다.
  raw = (raw:gsub("[\r\n\t]", ""))
  raw = (raw:gsub("^[%s\194\160]+", ""))
  raw = (raw:gsub("[%s\194\160]+$", ""))

  local ver, body = raw:match("^MSJ(%d+);?(.*)$")
  if not ver then
    return nil, "MSJ 로 시작하는 코드가 아닙니다. 코드 전체를 복사했는지 확인해 주세요."
  end
  if ver ~= MSJ_SAVE_VER then
    return nil, "코드 버전이 다릅니다 (코드 v"..ver.." / 이 카드 v"..MSJ_SAVE_VER..")"
  end

  -- 명세에 있는 키만 받는다. 오타나 장난 코드가 엉뚱한 변수를 만드는 것을 막는다.
  local keys, allow = svKeys(), {}
  for _, k in ipairs(keys) do allow[k] = true end

  local got, n = {}, 0
  for pair in body:gmatch("[^;]+") do
    local k, v = pair:match("^([^=]+)=(.*)$")
    if k and allow[k] then got[k] = svDec(v); n = n + 1 end
  end
  if n == 0 then
    return nil, "읽을 수 있는 값이 없습니다. 코드가 중간에 잘렸을 수 있습니다."
  end

  -- 1) 전 항목을 비운다. 새 방에 남아 있던 값이 섞이지 않게 한다.
  for _, k in ipairs(keys) do setChatVar(tid, k, "") end
  -- 2) 코드값 덮어쓰기
  for k, v in pairs(got) do setChatVar(tid, k, v) end
  -- 3) 화면 상태는 코드에 없다. 설정이 끝난 화면으로 못박는다.
  --    옛 방에서 선택기를 열어둔 채 코드를 만들었어도 새 방은 본편에서 시작한다.
  setChatVar(tid, "setup_init", "1")
  setChatVar(tid, "setup_num",  "9")
  setChatVar(tid, "char_pop",   "0")
  setChatVar(tid, "set_open",   "0")
  setChatVar(tid, "edit_target","1")
  setChatVar(tid, "msj_rb",     "")
  setChatVar(tid, "msj_save",   "")
  return n
end

function exportSave(tid)
  setChatVar(tid, "msj_save", buildSaveCode(tid))
  setChatVar(tid, "set_open", "1")
  pcall(alertNormal, tid,
    "세이브 코드를 만들었습니다.\n설정창의 코드 상자를 탭하면 전체 선택됩니다. 복사해 두세요.\n\n"
    .."새 방을 연 뒤 환경세팅 → [코드 넣기] 에 붙여넣으면 그대로 이어집니다.")
  redraw(tid)
end

function clearSaveCode(tid)
  setChatVar(tid, "msj_save", "")
  redraw(tid)
end

importSave = async(function(tid)
  local raw = alertInput(tid, "세이브 코드를 붙여넣어 주세요 (MSJ"..MSJ_SAVE_VER.."; 로 시작)"):await()
  if type(raw) ~= "string" and type(raw) ~= "number" then return end
  local n, err = applySaveCode(tid, tostring(raw))
  if not n then
    pcall(alertError, tid, "불러오기 실패 — "..(err or "알 수 없는 오류"))
    return
  end
  pcall(alertNormal, tid, "불러오기 완료 — "..n.."개 항목을 복원했습니다.")
  redraw(tid)
end)

-- 환경세팅 팝업.
-- 인물 편집은 여기 두지 않는다. 첫 메시지 선택기가 이미 그 기능을 갖고 있고,
-- 같은 화면을 LUA 로 한 벌 더 만들면 라벨 하나 바꿀 때 두 군데를 고쳐야 한다.
-- 인물은 캐릭터 설정 버튼이 그 선택기를 오버레이로 띄운다.
function buildSetPopup(tid)
  local ma = setOpt(tid, "msj_mult_aff")
  local ml = setOpt(tid, "msj_mult_lewd")
  local mg = setOpt(tid, "msj_mult_guilt")
  local ms = setOpt(tid, "msj_mult_susp")

  -- 배수 6단계. 0.25 는 아주 천천히, 10 은 몇 턴 만에 끝까지 간다.
  local MULT_STEP = {"0.25","0.5","1","2","5","10"}
  local function multRow(cur, prefix)
    local out = {}
    for _, v in ipairs(MULT_STEP) do
      out[#out+1] = chip(cur, v, prefix..(v:gsub("%.", "")), "\u{00D7}"..v)
    end
    return table.concat(out)
  end

  local left = box("변동 배수",
        item("호감 증가", multRow(ma, "multAff"))
     .. item("음란 증가", multRow(ml, "multLewd"))
     .. item("죄책 감소", multRow(mg, "multGuilt"))
     .. item("의심 증가", multRow(ms, "multSusp")))

  -- 출연은 이름만 있으면 된다. 수치는 바로 위 STATUS 패널이 이미 보여준다.
  local sc = {}
  for i = 1, 4 do
    local on = (gv(tid, "w"..i.."_scene", "0") == "1")
    sc[#sc+1] = '<span class="msj-chip' .. (on and " on" or "") .. '" risu-trigger="scene' .. i .. '">'
             .. gv(tid, "w"..i.."_name", "?") .. '</span>'
  end
  local iz = setOpt(tid, "msj_img")
  local tz = setOpt(tid, "msj_tap")
  local nf = setOpt(tid, "msj_nsfw")

  -- 셋 다 대화 중 스프라이트에 걸린다. 캐릭터 설정 카드는 건드리지 않는다.
  local view = box("이미지",
        item("에셋 크기",     chip(iz,"basic","imgBasic","기본") .. chip(iz,"big","imgBig","크게"))
     .. item("모바일 이미지", chip(tz,"on","tapZoomOn","탭 확대") .. chip(tz,"off","tapZoomOff","항상 전체"))
     .. item("NSFW",         chip(nf,"1","nsfwOn","표시") .. chip(nf,"0","nsfwOff","가림")))

  -- 동작 칩은 인물 칩과 같은 줄에 두지 않는다.
  -- 토글(선택 상태가 남는 것)과 실행(누르면 끝나는 것)이 섞이면
  -- 어느 것이 켜져 있는 상태인지 읽히지 않는다.
  local right = box("시뮬 출연",
       '<div class="msj-chips">' .. table.concat(sc) .. '</div>'
    .. '<div class="msj-chips" style="margin-top:6px;">'
    .. actChip("sceneAll",   "전체 선택")
    .. actChip("sceneClear", "전체 해제")
    .. '</div>'
    .. '<div class="msj-note">이번 시뮬에서 나올 인물을 고르세요.</div>')

  -- 채팅방 이사. 코드 상자는 만들었을 때만 뜬다.
  -- 늘 띄워두면 쓰지 않는 사람에게도 긴 문자열이 계속 보인다.
  local sv  = gv(tid, "msj_save", "")
  local box2 = '<div class="msj-chips">'
    .. actChip("exportSave", "코드 만들기")
    .. actChip("importSave", "코드 넣기")
    .. ((sv ~= "") and actChip("clearSaveCode", "코드 지우기") or "")
    .. '</div>'
  if sv ~= "" then
    -- user-select:all 이라 한 번 탭하면 전체가 잡힌다. 긴 문자열을 손으로 끌 필요가 없다.
    box2 = box2 .. '<div style="margin-top:7px;padding:8px 9px;border-radius:8px;'
      .. 'background:rgba(0,0,0,0.34);border:1px solid rgba(154,110,255,0.28);'
      .. 'font-size:10.5px;line-height:1.45;color:#CBB8FF;word-break:break-all;'
      .. 'max-height:112px;overflow-y:auto;-webkit-user-select:all;user-select:all;'
      .. 'cursor:text;">' .. sv .. '</div>'
  end
  local move = box("채팅방 이사",
       box2
    .. '<div class="msj-note">대화가 길어져 새 방으로 옮길 때 씁니다. '
    .. '코드를 만들어 복사해 두고, 새 방에서 [코드 넣기] 에 붙여넣으세요. '
    .. '인물 구성과 수치, 환경세팅이 그대로 따라옵니다.</div>')

  return "<!--MSJ-->" .. MSJ_SET_CSS
    .. '<div class="msj-scrim" risu-trigger="closeSetup"></div>'
    .. '<div class="msj-pop">'
    .. '<div class="msj-pop-hd"><span class="msj-pop-k">SETTINGS</span>'
    .. '<span class="msj-pop-t">환경세팅</span>'
    .. '<span class="msj-pop-x" risu-trigger="closeSetup">\u{2715}</span></div>'
    .. '<div class="msj-set msj-set-one">' .. left .. view .. right .. move .. '</div>'
    .. '<div class="msj-pop-ft">'
    .. '<span class="msj-pop-close" risu-trigger="closeSetup">닫기</span></div>'
    .. '</div><!--/MSJ-->'
end



-- 상태 변동 카드 (넥서스 방식)
--------------------------------------------------
-- 축마다 독립적으로 gsub 를 돌려 태그가 있던 자리에 카드 한 장을 꽂는다.
-- AI 가 세 축 중 하나만 뱉어도, 셋 다 뱉어도, 하나도 안 뱉어도 그대로 대응된다.
-- 축끼리 묶지 않는다. 호감·음란·죄책은 서로 무관하게 움직이는 값이다.

local MSJ_DC_CSS = [[<style>.msj-dc{box-sizing:border-box;max-width:100%;margin:6px 0;padding:10px 12px;background:#1e1e22;border:1px solid #2e2e34;border-radius:10px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;}.msj-dc+.msj-dc{margin-top:8px;}.msj-dc-h{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:700;color:#e8e8ec;padding-bottom:7px;border-bottom:1px solid #2e2e34;word-break:keep-all;}.msj-dc .r{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 7px;margin:6px 0 0;font-size:12.5px;line-height:1.55;color:#c8c8d0;word-break:keep-all;overflow-wrap:anywhere;}.msj-dc b{flex-shrink:0;font-size:12px;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums;}.msj-dc u{margin-left:1px;font-size:11px;color:#6b6b75;text-decoration:none;}.msj-dc-f{display:flex;flex-wrap:wrap;align-items:baseline;gap:3px 9px;}.msj-dc-f b{font-size:13px;}.msj-dc-tg{margin-left:auto;flex-shrink:0;padding:2px 9px;border-radius:6px;cursor:pointer;-webkit-tap-highlight-color:transparent;font-size:10.5px;font-weight:700;color:#928AA4;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.12);}.msj-dc-tg:hover{color:#EDE8F5;border-color:rgba(154,110,255,0.55);background:rgba(154,110,255,0.14);}.msj-dc em{font-size:10px;font-style:normal;font-weight:800;color:#9A6EFF;}.msj-dc small{flex-shrink:0;font-size:13px;font-weight:700;color:#e8e8ec;}.msj-dc .a{color:#B6A6D8;}.msj-dc .l{color:#D89AA8;}.msj-dc .g{color:#8AC5C5;}.msj-dc .s{color:#D8A35C;}.msj-dc .x{color:#f04646;}@media(max-width:600px){.msj-dc{padding:9px 10px;}.msj-dc .r{gap:2px 6px;font-size:12px;}.msj-dc b{font-size:11.5px;}.msj-dc-h{font-size:12.5px;}.msj-dc-f b,.msj-dc small{font-size:12.5px;}}</style>]]

-- 축 정의. ord 는 카드 행 순서, cls 는 색 클래스(CSS 쪽에 있다).
local MSJ_AX = {
  aff   = { label = "호감", ord = 1, cls = "a" },
  lewd  = { label = "음란", ord = 2, cls = "l" },
  guilt = { label = "죄책", ord = 3, cls = "g" },
  -- 의심은 오르는 쪽이 위협이지만 위험색(빨강)을 붙이지 않는다.
  -- 빨강은 "호감·음란이 깎였다"는 뜻으로 이미 쓰이고 있어서, 여기에 겹치면
  -- 한 카드 안에서 빨간 행이 서로 다른 두 가지를 뜻하게 된다.
  -- 앰버 자체가 경고색이므로 방향과 무관하게 이 색을 유지한다.
  susp  = { label = "의심", ord = 4, cls = "s", fixed = true },
}

-- HTML 이스케이프. 카드와 툴팁 둘 다 쓰므로 둘 중 앞선 곳에 둔다.
local function htmlEsc(s)
  return (tostring(s or ""):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

-- 상태 변동 카드. 축이 몇 개든 한 장으로 끝난다.
-- 예전엔 축마다 카드를 한 장씩 꿂았는데, 4축이 한 번에 뜨면
-- 테두리가 네 개 쌓이면서 본문보다 카드가 길어졌다.
--
-- rows : 정렬이 끝난 { ax, who, d, cur, reason, mult, safe } 배열
-- fold : true 면 사유를 감추고 한 줄 요약만 남긴다
--
-- 단계 이름(애정·각성·무감각)은 넣지 않는다.
-- 수치가 옆에 있고 상태 패널이 같은 것을 다시 보여주므로 세 번째 표기다.
--
-- 인물은 등장순으로 묶는다. 한 턴에 두 인물이 함께 움직였을 때만
-- 덩어리가 둘로 갈리고, 보통은 하나다.
function buildMsjDeltaCard(rows, fold)
  if not rows or #rows == 0 then return "" end

  -- 인물별로 묶는다. 순서는 rows 에 이미 잡혀 있으므로 그대로 따른다.
  local groups, at = {}, {}
  for _, r in ipairs(rows) do
    local k = at[r.who]
    if not k then
      k = #groups + 1
      at[r.who] = k
      groups[k] = { who = r.who, list = {} }
    end
    local L = groups[k].list
    L[#L+1] = r
  end

  -- 칩은 SET_TRIG 에서 만들어진 함수를 그대로 부른다.
  -- 접힘 상태는 msj_dcfold 변수 하나라, 화면에 떠 있는 카드가 함께 접힌다.
  local tg = '<span class="msj-dc-tg" risu-trigger="'
    .. (fold and "dcFull" or "dcBrief") .. '">'
    .. (fold and "펴기" or "접기") .. '</span>'

  local function delta(r, withTotal)
    local mtx = ""
    if r.mult and r.mult ~= 1 then
      local ms = (r.mult == math.floor(r.mult)) and tostring(math.floor(r.mult)) or tostring(r.mult)
      mtx = '<em>(\u{00D7}' .. ms .. ')</em>'
    end
    -- 색은 CSS 클래스로 낸다. 인라인 style 이 붙은 span 은
    -- editDisplay 가 잘라내는 사례가 있고, 4행이면 같은 색값을 네 번 실어 보낸다.
    return '<b class="' .. (r.safe and r.ax.cls or "x") .. '">'
      .. r.ax.label .. " " .. ((r.d > 0) and "+" or "") .. r.d .. mtx
      .. (withTotal and ('<u>(' .. r.cur .. '/300)</u>') or "")
      .. '</b>'
  end

  -- 인물마다 카드 한 장. 예전에는 한 장 안에서 헤더로만 갈랐는데,
  -- 두 인물이 같이 움직인 턴에 어디까지가 누구 것인지 눈으로 안 끊겼다.
  -- CSS 는 맨 앞에 한 번만 싣고 카드 div 만 이어붙인다.
  local b = { "<!--MSJ-->", MSJ_DC_CSS }

  for gi, g in ipairs(groups) do
    b[#b+1] = '<div class="msj-dc">'
    if fold then
      -- 접힘 : 인물당 한 줄. 사유는 내보내지 않는다.
      -- 숨기는 것과 안 보내는 것은 다르다. 숨기기만 하면 길이가 그대로라 실익이 없다.
      b[#b+1] = '<div class="msj-dc-f"><small>' .. htmlEsc(g.who) .. '</small>'
      for _, r in ipairs(g.list) do b[#b+1] = delta(r, false) end
      if gi == 1 then b[#b+1] = tg end
      b[#b+1] = '</div>'
    else
      -- 헤더는 행이 하나뿐이어도 세운다. 카드가 갈라진 뒤로는 「인물당 한 행」이
      -- 흔한 모양이라, 그때만 이름을 행 앞에 붙이면 카드마다 생김새가 달라진다.
      b[#b+1] = '<div class="msj-dc-h">'
        .. htmlEsc(g.who) .. ((gi == 1) and tg or "") .. '</div>'
      for _, r in ipairs(g.list) do
        b[#b+1] = '<p class="r">' .. delta(r, true) .. htmlEsc(r.reason or "") .. '</p>'
      end
    end
    b[#b+1] = '</div>'
  end

  -- 접기 칩은 첫 카드에만 둔다(gi == 1). 상태가 msj_dcfold 변수 하나라
  -- 어느 칩을 눌러도 전부 같이 접히므로, 카드마다 달면 같은 스위치가 여러 개가 된다.
  b[#b+1] = '<!--/MSJ-->'
  return table.concat(b)
end

-- 상태 패널 CSS
--
-- 4열은 무조건 확보한다. 여자 슬롯이 4개이므로 한 줄에 넷이 들어가는 것이
-- 이 패널의 기본 형태다. 폭이 모자라다고 2열로 접으면 안 된다.
--
-- 4열/2열 분기를 @media 에서 @container 로 옮겼다.
-- @media 는 화면 폭을 재는데 패널이 받는 폭은 채팅 말풍선 폭이다.
-- PC 화면이 1920 이어도 말풍선이 600 이면 @media 는 4열을 유지했고,
-- 그 안에서 「죄책(죄책감)」이 잘려 …으로 떨어졌다.
--
-- 폭을 벌리는 대신 축 한 칸을 두 줄로 쌓았다. 예전에는 축 이름과 단계가
-- 한 줄에 붙어 있어 둘을 더한 폭(65px)이 필요했는데, 단계를 아랫줄로 내리면
-- 둘 중 긴 쪽만 있으면 된다.
--   축 이름 2자 12.5px  →  24.4px
--   단계 3자 + 괄호 11.5px → 40.6px      → 긴 쪽 41px, 여유 붙여 44px
-- 4열이 성립하는 패널 폭 :
--   (44*2 + 축간격 7 + 칸패딩 20) * 4 + 칸간격 8*3 + 패널패딩 24 = 508px
-- 508 이면 어지간한 말풍선은 다 넘으므로 PC 에서는 사실상 항상 4열이다.
-- 경계는 510 으로 두고, 그 아래(좁은 폰)에서만 2열로 떨어뜨린다.
--
-- 곁들여 패널·칸 패딩과 간격을 줄여 축 한 칸당 10px 가량을 되찾았고,
-- .msj-st-ax b 의 말줄임을 걷어내고 줄바꿈으로 바꿨다.
-- 컨테이너 쿼리를 모르는 구형 브라우저에서도 잘리는 대신 접힌다.
local MSJ_ST_CSS = [[<style>.msj-st{box-sizing:border-box;width:100%;max-width:100%;margin:8px 0;padding:13px 12px 14px;--axmin:44px;background:linear-gradient(135deg,#141418 0%,#1a1a20 100%);border:1px solid #2e2e34;border-radius:10px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;}.msj-st-hd{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:11px;}.msj-st-ttl{font-size:10.5px;font-weight:800;letter-spacing:3px;color:#9A6EFF;text-transform:uppercase;}.msj-st-btns{display:flex;gap:6px;flex-shrink:0;}.msj-st-btn{padding:5px 13px;border-radius:7px;font-size:11.5px;font-weight:700;color:#b0b0ba;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.12);cursor:pointer;-webkit-tap-highlight-color:transparent;white-space:nowrap;transition:all .15s;}.msj-st-btn:hover{color:#EDE8F5;border-color:rgba(154,110,255,0.6);background:rgba(154,110,255,0.12);}.msj-st-gr{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;}.msj-st-cell{box-sizing:border-box;min-width:0;padding:11px 10px 12px;border-radius:9px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.07);}.msj-st-nm{display:block;font-size:16px;font-weight:800;color:#f2f2f6;letter-spacing:-0.4px;line-height:1.2;word-break:keep-all;overflow-wrap:anywhere;}.msj-st-job{display:block;margin-top:2px;font-size:12px;font-weight:600;color:#8a8a94;letter-spacing:-0.2px;line-height:1.3;word-break:keep-all;overflow-wrap:anywhere;}.msj-st-ty{display:block;margin-top:2px;padding-bottom:10px;margin-bottom:9px;border-bottom:1px solid rgba(255,255,255,0.08);font-size:12px;font-weight:700;color:#9A6EFF;letter-spacing:-0.2px;line-height:1.3;word-break:keep-all;}.msj-st-ax{display:grid;grid-template-columns:repeat(auto-fit,minmax(var(--axmin),1fr));gap:6px 7px;}.msj-st-sl{display:flex;flex-wrap:wrap;gap:4px 13px;}.msj-st-ax b,.msj-st-sl b{min-width:0;font-size:12.5px;font-weight:800;letter-spacing:-0.3px;line-height:1.25;}.msj-st-sl b{white-sp