255,0.06);}.msj-st-tk{flex:0 0 auto;width:104px;font-size:11.5px;font-weight:800;color:#C2A878;letter-spacing:-0.2px;line-height:1.5;word-break:keep-all;}.msj-st-tv{flex:1 1 auto;min-width:0;font-size:12.5px;font-weight:500;color:#cfcfd8;letter-spacing:-0.2px;line-height:1.6;word-break:keep-all;overflow-wrap:anywhere;}@media(max-width:600px){.msj-st-tip{padding:10px 11px;}.msj-st-tr{flex-direction:column;gap:1px;padding:5px 0;}.msj-st-tk{width:auto;font-size:11px;}.msj-st-tv{font-size:12px;}}</style>]]
-- 축 한 줄. 라벨 / 단계 이름 / 수치.
-- 게이지는 뺐다. 4열에서 한 칸이 좁아 막대가 정보를 더하지 못하고 높이만 먹는다.
-- 그 자리를 단계 이름(무관심·인지·끌림 …) 키우는 데 썼다. 숫자보다 이쪽이 읽는 값이다.
-- 호버 툴팁. 그 칸 인물의 현재 셀 6줄을 그대로 펼친다.
-- 패널이 보여주는 것은 수치와 단계 이름뿐이라, 그 좌표가 실제로 어떤 지시문으로
-- 나가는지 화면에서 확인할 방법이 없었다. OOC 와 같은 getCellRows 를 쓰므로
-- 여기 보이는 것이 곧 모델에게 나간 것이다.
--
-- 위치 기준은 칸이 아니라 패널(.msj-st)이다. 칸에 position 을 주면 4열 중
-- 양끝 칸에서 툴팁이 패널 밖으로 삐져나가 잘린다.
-- 칸 안의 축 하나. 「호감(애정)」 꼴이다. 수치는 넣지 않는다.
-- 4열 격자에서 한 칸이 좁아 수치까지 넣으면 단계 이름이 잘린다.
-- 숫자는 툴팁의 스탯 줄이 맡는다.
local function stAx(cls, label, tier)
  return '<b class="' .. cls .. '">' .. label
    .. '<i>(' .. htmlEsc(tier) .. ')</i></b>'
end

-- 툴팁 첫 줄. 네 축을 수치까지 붙여 한 줄로 늘어놓는다.
-- 의심 수치는 여자가 아니라 남편 쪽(h{n}_susp)에 쌓인다.
-- 예전 패널은 w{i}_susp 를 읽고 있었는데 그런 변수는 만들어진 적이 없어
-- 의심이 언제나 0 으로 떠 있었다.
local ST_AX = {
  { "a", "호감", "H_kr", "aff"   },
  { "l", "음란", "L_kr", "lewd"  },
  { "g", "죄책", "G_kr", "guilt" },
  { "s", "의심", "S_kr", "susp"  },
}

local function suspOf(tid, p)
  return gn(tid, "h" .. gn(tid, p .. "hus", 1) .. "_susp", 0)
end

local function stStat(tid, p)
  local b = {}
  for _, a in ipairs(ST_AX) do
    local v = (a[4] == "susp") and suspOf(tid, p) or gn(tid, p .. a[4], 0)
    b[#b+1] = '<b class="' .. a[1] .. '">' .. a[2]
      .. '<i>(' .. htmlEsc(gv(tid, p .. a[3], "?")) .. ')</i>'
      .. '<u>' .. v .. '</u></b>'
  end
  return table.concat(b)
end

local function stTip(tid, i, name)
  if type(getCellRows) ~= "function" then return "" end
  local p = "w"..i.."_"
  local rows = getCellRows(gn(tid, p.."type", 1), gn(tid, p.."H", 1),
                           gn(tid, p.."L", 1),    gn(tid, p.."G", 1))
  if not rows then return "" end
  -- 의심은 셀(getCellRows)이 아니라 남편 쪽에서 온다. 마지막 줄로 덧붙인다.
  -- 문구는 OOC 와 같은 것을 쓴다. 화면과 프롬프트가 갈라지면 확인용으로 못 쓴다.
  -- 성적 취향과 페티시도 OOC 와 같은 조건, 곧 단계와 무관하게 늘 보인다.
  local pf = gv(tid, p.."pref", "")
  if pf ~= "" then rows[#rows+1] = { "성적 취향", pf } end
  local fx = gv(tid, p.."fetish", "")
  if fx ~= "" then rows[#rows+1] = { "성적 페티시", fx } end
  local act = gv(tid, p.."hsusp_act", "")
  if act ~= "" then rows[#rows+1] = { "남편의 의심", act } end

  -- 자녀와 남편. 셀이 아니라 인물 설정에서 온다.
  -- OOC 프로필과 같은 값을 같은 순서로 둔다. 툴팁은 프롬프트 확인용이라
  -- 여기서 형식이 갈라지면 대조가 안 된다.
  rows[#rows+1] = { "자녀", gv(tid, p.."kids_kr", "없음") }

  local hi  = gn(tid, p.."hus", i)
  local h   = "h"..hi.."_"
  rows[#rows+1] = {
    "남편",
    gv(tid, h.."name", "?").." ("..gv(tid, h.."age", "?").."세 · "
      ..gv(tid, h.."job_kr", "?")..") · "..gv(tid, h.."rel_kr", "?")
  }

  -- 툴팁은 OOC 와 같은 것을 보여주는 게 존재 이유라, 치환도 같이 건다.
  -- 여기서 안 걸면 프롬프트엔 「연인」이 나가는데 화면엔 「남편」이 남는다.
  local bf = wIsBf(tid, i)
  if bf then
    for _, r in ipairs(rows) do r[1] = bfText(r[1]); r[2] = bfText(r[2]) end
  end

  local b = { '<div class="msj-st-tip"><div class="msj-st-th">' .. htmlEsc(name) .. '</div>' }
  -- 수치는 칸에서 뺐으므로 여기가 유일한 확인 지점이다. 성격 줄보다 위에 둔다.
  b[#b+1] = '<div class="msj-st-tr"><span class="msj-st-tk">스탯</span>'
    .. '<span class="msj-st-tv msj-st-sl">' .. stStat(tid, p) .. '</span></div>'
  for _, r in ipairs(rows) do
    b[#b+1] = '<div class="msj-st-tr">'
      .. '<span class="msj-st-tk">' .. htmlEsc(r[1]) .. '</span>'
      .. '<span class="msj-st-tv">' .. htmlEsc(r[2]) .. '</span>'
      .. '</div>'
  end
  b[#b+1] = '</div>'
  return table.concat(b)
end

-- 시뮬 출연 인물의 상태 패널. 설정 버튼이 함께 붙는다.
-- 한 칸 구성 : 이름 / 직업 / 성격 / 4축 2x2
-- 축 칸에는 「호감(애정)」처럼 단계 이름까지만 넣고 수치는 뺐다.
-- 수치는 마우스오버 툴팁 첫 줄에 네 축이 한 줄로 늘어선다.
-- 데스크톱 4열, 태블릿·모바일 2열(2x2). 1열로는 떨어뜨리지 않는다.
function buildStatPanel(tid)
  local cells, any = {}, false
  for i = 1, 4 do
    if gv(tid, "w"..i.."_scene", "0") == "1" then
      any = true
      local p  = "w"..i.."_"
      local nm = gv(tid, p.."name", "?")
      -- 이름 옆에 나이를 붙인다. 툴팁 제목도 같은 문자열을 쓴다.
      local nmAge = nm.."("..gv(tid, p.."age", "?")..")"
      -- tabindex 는 모바일용이다. hover 가 없는 환경에서도 탭하면 focus 가 잡혀 툴팁이 뜬다.
      cells[#cells+1] = '<div class="msj-st-cell" tabindex="0">'
        .. '<div class="msj-st-nm">'  .. nmAge .. '</div>'
        .. '<div class="msj-st-job">' .. gv(tid, p.."job_kr",  "?") .. '</div>'
        .. '<div class="msj-st-ty">'  .. gv(tid, p.."type_kr", "?") .. '형</div>'
        .. '<div class="msj-st-ax">'
        .. stAx("a", "호감", gv(tid, p.."H_kr", "?"))
        .. stAx("l", "음란", gv(tid, p.."L_kr", "?"))
        .. stAx("g", "죄책", gv(tid, p.."G_kr", "?"))
        .. stAx("s", "의심", gv(tid, p.."S_kr", "?"))
        .. '</div>'
        .. stTip(tid, i, nmAge)
        .. '</div>'
    end
  end
  local inner
  if any then
    inner = '<div class="msj-st-gr">' .. table.concat(cells) .. '</div>'
  else
    inner = '<div class="msj-st-em">시뮬에 출연 중인 인물이 없습니다</div>'
  end
  return "<!--MSJ-->" .. MSJ_ST_CSS
    .. '<div class="msj-st">'
    .. '<div class="msj-st-hd"><span class="msj-st-ttl">STATUS</span>'
    .. '<span class="msj-st-btns">'
    .. '<span class="msj-st-btn" risu-trigger="openSetup">환경세팅</span>'
    .. '<span class="msj-st-btn" risu-trigger="openChar">캐릭터 설정</span>'
    .. '</span></div>'
    .. inner
    .. '</div><!--/MSJ-->'
end
--------------------------------------------------
-- [SET] 설정 팝업 트리거
--------------------------------------------------
-- 첫 메시지의 시나리오 선택기와는 완전히 분리해서 돌린다.
-- 기존 트리거(setWJob · pickIdxN …)를 그대로 부르되, 그것들이 건드리는
-- setup_num 을 호출 전 값으로 되돌려 놓아 선택기가 따라 움직이지 않게 한다.

-- 환경세팅. 배수와 출연 토글만 있다.
function openSetup(tid)
  setChatVar(tid, "set_open", "1")
  redraw(tid)
end

-- 캐릭터 설정. 첫 메시지 선택기를 그대로 재활용하되 오버레이로 띄운다.
-- char_pop 이 1이면 정규식이 .SCAT88-ov 로 감싸고 시나리오 프리셋을 감춘다.
--   0 : 첫 설정. 첫 메시지 안에 인라인으로 그려지고 프리셋이 보인다
--   1 : 진행 중 수정. 화면 위에 뜨고 프리셋은 없다
-- 새 채팅을 열자마자 오버레이가 화면을 덮으면 안 되므로 기본값은 0이다.
-- 진행 중에 프리셋을 누르면 4명이 통째로 갈리고 수치도 초기화되므로 그때는 감춘다.
function openChar(tid)
  setChatVar(tid, "set_open", "0")
  setChatVar(tid, "char_pop", "1")
  setChatVar(tid, "setup_num", "1")
  redraw(tid)
end

-- 선택기 닫기. 환경세팅의 closeSetup 과 이름을 나눠야 한다.
-- 예전에 같은 이름을 쓰다가 창 두 개가 겹쳐 서로를 닫는 문제가 있었다.
function closeChar(tid)
  setChatVar(tid, "setup_num", "9")
  setChatVar(tid, "char_pop", "0")
  redraw(tid)
end

function closeSetup(tid)
  setChatVar(tid, "set_open", "0")
  redraw(tid)
end

-- 옵션 칩 트리거를 한 번에 만든다
-- 배수 트리거. 0.25 · 0.5 · 1 · 2 · 5 · 10
-- 함수 이름에서 소수점을 뺀다. multAff025 / multAff05 / multAff1 ...
local SET_TRIG = {}
for _, ax in ipairs({{"Aff","msj_mult_aff"}, {"Lewd","msj_mult_lewd"},
                     {"Guilt","msj_mult_guilt"}, {"Susp","msj_mult_susp"}}) do
  for _, v in ipairs({"0.25","0.5","1","2","5","10"}) do
    SET_TRIG["mult"..ax[1]..(v:gsub("%.", ""))] = { ax[2], v }
  end
end

SET_TRIG.imgBasic  = { "msj_img",     "basic" }
SET_TRIG.imgBig    = { "msj_img",     "big"   }
SET_TRIG.nsfwOn    = { "msj_nsfw",    "1"     }
SET_TRIG.nsfwOff   = { "msj_nsfw",    "0"     }
SET_TRIG.tapZoomOn  = { "msj_tap",    "on"    }
SET_TRIG.tapZoomOff = { "msj_tap",    "off"   }
-- 변동 카드 접기·펴기. 카드 안 칩이 이 둘을 그대로 불러서
-- 토글 전용 함수를 따로 두지 않는다. 설정 팝업에서도 같은 이름을 쓴다.
SET_TRIG.dcFull    = { "msj_dcfold",  "0"     }
SET_TRIG.dcBrief   = { "msj_dcfold",  "1"     }

for fn, kv in pairs(SET_TRIG) do
  _G[fn] = function(tid)
    setChatVar(tid, kv[1], kv[2])
    redraw(tid)
  end
end

function buildStw(tid)
  local d = gv(tid, "st_date",  "-")
  local t = gv(tid, "st_time",  "-")
  local p = gv(tid, "st_place", "-")
  if d == "" then d = "-" end
  if t == "" then t = "-" end
  if p == "" then p = "-" end
  return "<!--MSJ-->" .. MSJ_STW_CSS
    .. '<div class="msj-stw">'
    .. '<div class="msj-stw-l">'
    .. '<span class="msj-stw-date">'..d..'</span>'
    .. '<span class="msj-stw-hour">'..t..'</span>'
    .. '</div>'
    .. '<div class="msj-stw-r"><span class="msj-stw-place">'..p..'</span></div>'
    .. '</div><!--/MSJ-->'
end

--------------------------------------------------
-- [주입] pool 조회 → OOC 조립 → 프롬프트 삽입
--------------------------------------------------
-- 주입 방식은 승인연애와 같다.
--   onStart      : 마지막 유저 메시지 뒤에 OOC 블록을 붙인다 (AI 요청 직전)
--   editRequest  : 지난 턴에 남은 블록을 지운다 (히스토리 오염 방지)
--   editDisplay  : 화면에서도 블록을 숨긴다

-- 연기 지침. 인물 블록보다 먼저 나간다.
--
-- 6컬럼을 평평한 목록으로 던지면 모델이 전부를 매 턴 균등하게 반영하려 든다.
-- 잡담 장면에서 죄책감 심리를 서술하고 피임 태도가 뜬금없이 튀어나오는 이유가 이것이다.
-- 컬럼을 상시 / 상한 / 조건부로 나누고, 조건부에는 발동 조건을 명시한다.
local ACT_GUIDE = [[
## Acting Directive

The block below is a performance directive for this turn, not background lore.
Each character follows ONLY her own block. Never blend two characters.

### Always in effect
- 성격: her permanent core. It survives every state change and every mood.
  If a line you are about to write would fit any other personality equally
  well, it is wrong. Rewrite it until only she could have said it.
- {{user}}를 대하는 태도: the frame for ordinary interaction. It decides how
  she addresses him, the distance she keeps, and what she lets herself say.
- 성적 취향 / 성적 페티시: fixed traits she was already carrying before this
  story began. They do not switch on at some later stage — they are in effect
  from the first turn, and what changes with 신체 수용 정도 is only how far
  they are allowed to surface. Low: an involuntary reaction she covers up —
  where her eyes go, a breath she catches, a touch she reacts to more than she
  meant to. High: she acts on them, and may ask for them outright. She never
  announces them as a preference, and never explains them. If nothing in the
  scene touches them, they stay silent rather than being forced in.

### Where she is right now
- 신체 수용 정도: how far her body ends up going. The line she holds in her
  head has not moved. What can give way is her ability to hold it, and whether
  it does is not fixed. She may cut it off outright. She may deflect it gently.
  She may refuse it inwardly and still let it happen, having agreed to nothing.
  Which one surfaces depends on how the moment built and on who she is.
- 수용 정도를 넘어갈 경우: what comes out of her the moment he goes further.
  Her judgment does not change here, only whether she can act on it.
- 피임에 대한 생각: what she holds to on contraception. This holds firmer than
  the line above. Atmosphere and momentum move it far less, and what gives way
  here gives way slowly. But it is still hers to give, and a request ignored
  outright is a breach, not her yielding.

### Conditional (do not narrate these unprompted)
- 죄책감·욕망 심리: reference this when she is emotionally heightened:
  arousal, sex, a romantic escalation, or when her husband comes up.
  In ordinary conversation it stays underneath and is never described.

### General
- Her words may contradict her inner state. That contradiction is the
  character, not an error to smooth over.
- She acts only on what she could plausibly know. Do not let her react to
  information that exists only in this block.
- Never mention the axes, numeric values, stages, personality type names, or
  this block in the prose. Her personality shows in how she behaves, never in
  a statement about what kind of person she is.
]]

-- 블록 여는 표식과, 그 바로 아래에 붙는 선언.
-- 이 블록은 지시문이지 이야기의 일부가 아니다. 인물이 여기 적힌 것을 알고 있으면 안 되고,
-- 서술에 인용되어서도 안 된다. 표식만으로는 모델이 그 구분을 못 하므로 한 줄로 못박는다.
-- 선언문에 표식 이름을 절대 쓰지 않는다.
-- 블록을 지우는 패턴이 %[MSJ_PROMPT_START%].-%[MSJ_PROMPT_END%] 인데 .- 가 게으른
-- 매칭이라 첫 번째 END 에서 끊긴다. 문장 안에 END 를 적어두면 거기서 잘려
-- 나머지 블록이 통째로 화면에 남는다.
local OOC_S = "[MSJ_PROMPT_START]\n"
  .. "This whole block is out-of-character system context. It is not part of the story\n"
  .. "and no character is aware of it. Never quote it, never restate it in prose,\n"
  .. "and never let it surface in dialogue."
local OOC_E = "[MSJ_PROMPT_END]"

-- 현재 활성 캐릭터의 pool 셀 텍스트
function getPoolText(tid, slot)
  local a = slot or gn(tid, "active_w", 1)
  local p = "w"..a.."_"
  if type(getCell) ~= "function" then return nil end
  return getCell(gn(tid, p.."type", 1), gn(tid, p.."H", 1),
                 gn(tid, p.."L", 1),    gn(tid, p.."G", 1))
end

-- 캐릭터 설정 블록 (셋업에서 고른 값들)
-- 주어가 생략되면 뜻이 뒤집히는 관계들.
-- 관계 목록은 「{{user}} 입장에서 그 여자가 누구인가」인데,
-- 아래 다섯은 문구만으로는 주체가 안 드러난다.
--   자녀의 교직원 : 누구 자녀인가 ({{user}} 쪽이다)
--   학생의 학부모 : 누구 학생인가 (그 여자의 자녀가 {{user}}의 학생이다)
--   고객·이용자   : 문구는 여자를 가리키는 듯하나 실제로는 {{user}}가 고객이다
-- 4명이 한 프롬프트에 들어가면 서로의 자녀와 뒤섞이므로 OOC 에서만 풀어 쓴다.
-- 선택기 목록은 원문 그대로 둔다.
local function relPhrase(tid, p, ri, raw)
  if ri == 28 then return "{{user}}가 이용하는 서비스의 제공자" end
  if ri == 29 then return "{{user}}가 제공하는 서비스의 고객" end
  if ri == 30 then return "{{user}}와 같은 학교 학부모" end
  if ri == 31 then return "{{user}} 자녀의 교직원" end
  if ri == 32 then
    local kid = gv(tid, p.."kid_name", "")
    if kid ~= "" then return kid.." 학생의 학부모 ({{user}}가 담당 교직원)" end
    return "{{user}}가 가르치는 학생의 학부모"
  end
  return raw
end

-- 받침 유무로 은/는 을 고른다.
-- 한글 음절은 UTF-8 3바이트이고, (코드포인트 - 0xAC00) % 28 이 0이면 받침이 없다.
-- 이름이 매 슬롯마다 달라지므로 고정 조사를 쓰면 "임수빈는" 같은 게 나온다.
-- 끝 글자에 받침이 있는가. 한글이 아니면 nil.
-- Lua 문자열은 바이트 단위라 한글 한 자는 3바이트다.
local function hasJong(name)
  local n = #name
  if n < 3 then return nil end
  local b1, b2, b3 = name:byte(n-2), name:byte(n-1), name:byte(n)
  if not b1 or b1 < 0xE0 then return nil end
  local cp = (b1 % 0x10) * 4096 + (b2 % 0x40) * 64 + (b3 % 0x40)
  if cp < 0xAC00 or cp > 0xD7A3 then return nil end
  return ((cp - 0xAC00) % 28 ~= 0)
end

-- 조사 붙이기. josa(name, "받침없을때", "받침있을때")
-- 판정이 안 되면 받침 없는 쪽을 쓴다. 외국식 이름이나 기호에 무난하다.
local function josa(name, no, yes)
  local j = hasJong(name)
  return name .. ((j == true) and yes or no)
end

local function topic(name) return josa(name, "는", "은") end

local function buildProfile(tid, slot)
  local a = slot or gn(tid, "active_w", 1)
  local p = "w"..a.."_"
  local hi = gn(tid, p.."hus", 1)
  local h = "h"..hi.."_"
  -- 라벨에 이름을 박는다.
  -- 4명이 한 프롬프트에 들어가면 "자녀" 가 누구 자녀인지, "관계" 가 누구와의
  -- 관계인지 섞인다. 특히 R31 자녀의 교직원처럼 {{user}} 쪽 자녀를 가리키는
  -- 항목과 그 여자의 자녀가 같은 화면에 있으면 구분이 안 된다.
  -- 관계는 「{{user}} 입장에서 그 여자가 누구인가」이므로 방향까지 적는다.
  local nm = gv(tid, p.."name", "?")
  local hnm = gv(tid, h.."name", "?")
  local L = {}
  L[#L+1] = nm.."의 나이: "..gv(tid, p.."age", "?").."세"
  L[#L+1] = nm.."의 직업: "..gv(tid, p.."job_kr", "?")
  L[#L+1] = "{{user}} 입장에서 "..topic(nm)..": "
             ..relPhrase(tid, p, gn(tid, p.."rel", 1), gv(tid, p.."rel_kr", "?"))
  L[#L+1] = nm.."의 자녀: "..gv(tid, p.."kids_kr", "?")
  -- 이름 뒤에 슬롯 코드를 한 번 박는다.
  -- 여자는 [Female1] 이름 형태로 블록 머리에 코드가 붙지만 남자는 그럴 자리가 없다.
  -- NPC LIST 표에도 있지만, 표와 본문을 오가며 맞춰보게 하는 것보다
  -- 이름이 나오는 자리에 한 번 더 붙여두는 편이 태그 오출력이 적다.
  L[#L+1] = nm.."의 "..(wIsBf(tid, a) and "연인" or "남편")..": "..hnm.."[Male"..hi.."]"
             .." ("..gv(tid, h.."age", "?").."세 · "..gv(tid, h.."job_kr", "?")..") · "
             ..gv(tid, h.."rel_kr", "?")
  L[#L+1] = "{{user}} 입장에서 "..topic(hnm)..": "..gv(tid, h.."user_kr", "?")
  L[#L+1] = "{{user}}와 "..nm.."의 불륜: "..gv(tid, p.."affair_kr", "없음")
  return table.concat(L, "\n")
end

-- 남편의 의심. 한 줄뿐이지만 셀 바깥에서 오는 유일한 상태값이다.
--
-- 예전에는 호감·음란·죄책 수치도 여기서 함께 내보냈는데 전부 걷어냈다.
-- 그 세 축은 이미 H/L/G 좌표로 셀을 골라내고, 셀 여섯 줄이 그 좌표를 서술로
-- 풀어놓는다. 수치를 덧붙이면 같은 것을 두 번 말하는 데다,
-- 셀은 5x5x3 해상도인데 수치는 300단계라 모델이 셀에 없는 중간 상태를 지어낸다.
-- ACT_GUIDE 가 "수치와 단계를 언급하지 말라"고 지시하면서 정작 수치를 실어보내던
-- 모순도 여기서 없어진다.
--
-- 의심만 남는 이유는 getCellRows 가 type/H/L/G 네 좌표만 쓰기 때문이다.
-- 의심 축은 셀에 아예 들어가지 않아, 이 줄이 없으면 프롬프트에서 통째로 사라진다.
local function buildState(tid, slot)
  local a = slot or gn(tid, "active_w", 1)
  local p = "w"..a.."_"
  local nm = gv(tid, p.."name", "?")
  local hnm = gv(tid, "h"..gn(tid, p.."hus", a).."_name", "남편")
  return josa(hnm, "가", "이").." "..(wIsBf(tid, a) and "여자친구" or "아내").." "
      ..josa(nm, "를", "을").." 의심하는 태도: "..gv(tid,p.."hsusp_act","")
end

-- 상태 태그 지시문 (매 턴 필수)
-- 예시는 고정값을 쓴다.
-- 예전에는 st_date / st_time / st_place 의 현재값을 그대로 예시에 박았는데,
-- 형식이 한 번 깨지면 그게 다음 턴 예시로 굳어 규칙과 충돌한다.
-- 모델이 "14시 30분" 을 뱉으면 예시도 "14시 30분" 이 되어
-- 바로 위의 "24h format" 규칙과 예시가 서로 다른 말을 한다.
-- 현재값은 직전 메시지의 [MSJ_STATUS] 태그로 이미 이력에 남아 있으므로
-- 예시까지 같은 값을 반복할 이유가 없다. 예시는 형식만 보여준다.
local function buildStatusOoc(tid)
  local L = {}
  L[#L+1] = "## Status Tag (required every turn)"
  L[#L+1] = "★ CRITICAL: Your response is INCOMPLETE without the [MSJ_STATUS] tag. Always end with it. ★"
  L[#L+1] = ""
  L[#L+1] = "[MSJ_STATUS TAG] Output exactly ONE tag at the VERY END of every response. NEVER mid-narration."
  L[#L+1] = ""
  L[#L+1] = "Format: [MSJ_STATUS::DATE::TIME::PLACE]"
  L[#L+1] = ""
  L[#L+1] = "Field order (3 fields, separated by ::):"
  L[#L+1] = "  1. DATE: 연도 월 일 (요일). e.g. 2026년 8월 6일 (목)"
  L[#L+1] = "  2. TIME: 24h format. e.g. 14:30"
  L[#L+1] = "  3. PLACE: 현재 장면의 위치. e.g. 아파트 복도 / 도서관 열람실 / 남편이 자는 안방"
  L[#L+1] = ""
  L[#L+1] = "Example:"
  L[#L+1] = "[MSJ_STATUS::2026년 8월 6일 (목)::14:30::아파트 복도]"
  L[#L+1] = ""
  L[#L+1] = "Rules:"
  L[#L+1] = "- Carry forward ALL fields every turn. Never omit fields."
  L[#L+1] = "- Advance date/time naturally based on scene progression."
  L[#L+1] = "- 서술 본문에는 시각을 숫자로 쓰지 않는다. 숫자는 이 태그에만 적는다."
  L[#L+1] = "- 장소는 남편의 부재·발각 위험과 직결된다. 집·직장·외부를 정확히 구분해 적는다."
  L[#L+1] = "- A response without [MSJ_STATUS] at the end is considered BROKEN. Always include it."
  L[#L+1] = "- Other tags may also be required this turn. Write those FIRST, then [MSJ_STATUS] as the FINAL line."
  L[#L+1] = ""
  L[#L+1] = "★ FINAL REMINDER: End EVERY response with [MSJ_STATUS::...]. No exceptions. ★"
  return table.concat(L, "\n")
end

-- 태그 지시문 (요약본)
-- 상세 판정 기준은 로어북 「[MSJ] State Judgment」에 있다. 여기서는 형식만 상기시킨다.
local TAG_GUIDE = [[
## State Tags (append at the very end of the response)

Four independent axes. Judge each one SEPARATELY. A change in one axis never implies a change in another.

  [msj_aff::FemaleN::±N::한글 사유]     Affinity toward {{user}}
  [msj_lewd::FemaleN::±N::한글 사유]    Physical reaction and sexual openness
  [msj_guilt::FemaleN::±N::한글 사유]   Guilt toward her husband (negative when it decreases)
  [msj_susp::FemaleN::±N::한글 사유]    Her husband's suspicion of the affair

ID rules
- Use the slot ID shown above as [FemaleN]. Never use the character's name in the ID field.
- The reason field is written in Korean and may contain her name.
- The number is a delta, not a total. The + or - sign is required.

When to output
- Only for characters who physically appeared and acted in the scene.
- Omit the tag entirely when that axis did not change.
- One tag per axis per character. Combine multiple events into a single net delta.

Scope of each axis
- aff   changes ONLY through direct interaction with {{user}}.
- lewd  changes through physical or situational arousal. It may change without {{user}}.
        A scene that touches her 성적 취향 or 성적 페티시 moves this axis faster
        than the same scene without it.
- guilt changes ONLY through events involving her husband (or partner) or family.
        {{user}} being kind to her does NOT reduce guilt.
- guilt is INVERTED: a higher value means stronger guilt. It normally decreases over time.

Detailed criteria are defined in these lorebook entries. Follow them:
  [MSJ] Affinity Judgment
  [MSJ] Lewdness Judgment
  [MSJ] Guilt Judgment
  [MSJ] Suspicion Judgment]]

-- 에셋 태그용 코드 대조표.
--
-- 이름은 프리셋마다 바뀌지만 슬롯 번호와 사진은 고정이다. 슬롯 1은 프리셋에 따라
-- 여덟 명의 이름을 갖는데 얼굴은 하나다. 그래서 자산 파일명은 이름이 아니라
-- 슬롯 코드를 따라가야 한다.
--
-- 로어북에 표를 박아두면 이름이 바뀌는 순간 거짓말이 되므로 매 턴 여기서 만든다.
-- 출연 중인 인물만 도는 것도 공짜로 따라온다. 로어북에 넷을 다 적으면
-- 무대에 없는 인물 태그가 나간다.
--
-- 「상대」로 적는 이유는 기혼과 미혼이 한 표에 섞이기 때문이다.
-- 「남편」이라 쓰면 미혼 인물 행이 틀리고, 치환은 인물 블록 안에만 걸린다.
--
-- 여자와 남자는 항상 1:1 이다. 남편을 고르는 두 경로(applyPick 의 hus / __wife)가
-- 전부 스왑으로 처리하므로 한 남자를 둘이 참조하는 상태가 만들어지지 않는다.
-- 그래서 중복 방어 없이 여자 슬롯을 그대로 훑으면 된다.
local function buildNpcList(tid)
  local rows = {}
  for i = 1, 4 do
    if gv(tid, "w"..i.."_scene", "0") == "1" then
      local p  = "w"..i.."_"
      local hi = gn(tid, p.."hus", i)
      local h  = "h"..hi.."_"
      local wn = gv(tid, p.."name", "?")
      local hn = gv(tid, h.."name", "?")
      rows[#rows+1] = "| "..wn.." | Female"..i.." | "
        ..gv(tid, p.."job_kr", "?").." | 여 | "..hn.." |"
      rows[#rows+1] = "| "..hn.." | Male"..hi.." | "
        ..gv(tid, h.."job_kr", "?").." | 남 | "..wn.." |"
    end
  end
  if #rows == 0 then return "" end
  -- 블록 안의 다른 지시문이 전부 영어라 여기만 한국어면 톤이 튄다.
  -- 표 안의 값은 이름과 직업이라 한국어 그대로 둔다.
  return "## NPC LIST\n"
    .. "Asset filenames use the Code, never the Korean name.\n"
    .. "A character absent from this table has no asset and must not be tagged.\n\n"
    .. "| Name | Code | Job | Sex | Partner |\n|---|---|---|---|---|\n"
    .. table.concat(rows, "\n")
end

function buildOoc(tid)
  local b = {}
  local any = false
  for i = 1, 4 do
    if gv(tid, "w"..i.."_scene", "0") == "1" then
      local cell = getPoolText(tid, i)
      if cell then
        if any then b[#b+1] = "" end
        any = true
        -- 인물 블록을 따로 조립한 뒤 그 인물에게만 치환을 건다.
        -- 4명이 한 프롬프트에 들어가므로 전체에 한 번 거는 방식은 쓸 수 없다.
        local one = {}
        one[#one+1] = "[Female"..i.."] "..gv(tid, "w"..i.."_name", "?")
        one[#one+1] = buildProfile(tid, i)
        one[#one+1] = buildState(tid, i)
        one[#one+1] = cell
        local blk = table.concat(one, "\n")
        if wIsBf(tid, i) then blk = bfText(blk) end
        b[#b+1] = blk
        -- 성적 취향과 페티시는 셀이 아니라 인물 고유값이라 getCellRows 바깥에서 붙인다.
        -- 단계와 무관하게 상시로 내보낸다. 타고난 성질이라 음란도가 낮다고
        -- 사라지는 것이 아니라, 드러나는 방식만 달라진다.
        -- 낮은 단계에서 이것이 노골적으로 튀어나오지 않게 잡는 것은 ACT_GUIDE 쪽 일이다.
        -- 사용자가 직접 쓴 값이라 bfText 치환 대상이 아니다. 그래서 블록 바깥에 붙인다.
        local nm = gv(tid, "w"..i.."_name", "?")
        local pf = gv(tid, "w"..i.."_pref", "")
        local fx = gv(tid, "w"..i.."_fetish", "")
        if pf ~= "" then b[#b+1] = nm .. "의 성적 취향: " .. nodash(pf) end
        if fx ~= "" then b[#b+1] = nm .. "의 성적 페티시: " .. nodash(fx) end
      end
    end
  end
  if not any then return "" end
  local npc = buildNpcList(tid)
  local out = OOC_S.."\n"..((npc ~= "") and (npc.."\n\n") or "")
      ..ACT_GUIDE.."\n"..table.concat(b, "\n")
      .."\n\n"..TAG_GUIDE
      .."\n\n"..buildStatusOoc(tid)
      .."\n"..OOC_E
  -- 마지막 안전망. 프로필·태그 지시문 등 어디서 새 엠대시가 들어와도 여기서 걸린다.
  return (out:gsub("\u{2014}", "-"))
end

onStart = function(tid)
  -- 셋업 게이트. initDefaults 보다 먼저 통과시킨다.
  -- 순서가 반대면, 인트로도 안 지난 상태에서 유저가 아무 말이나 쳤을 때
  -- 막히기 직전에 변수 전체가 만들어져 버린다.
  --
  -- setup_num 이 9(닫힘)가 아니면 설정 화면이 떠 있다는 뜻이다.
  --   0 인트로 / 1 선택기 / 2·4 인물 편집 / 6 항목 선택
  -- 진행 중 [캐릭터 설정] 으로 다시 열었을 때도 같은 게이트가 걸린다.
  -- 승인연애와 같은 순서로 처리한다. 경고 → stopChat → 방금 들어온 유저 메시지 제거 → 갱신.
  if gv(tid, "setup_num", "0") ~= "9" then
    local msg
    if gv(tid, "setup_init", "0") ~= "1" then
      msg = "[시작하겠습니다] 를 눌러 인물 구성을 먼저 마쳐주세요."
    else
      msg = "[이 구성으로 시작하기] 를 눌러야 진행됩니다."
    end

    pcall(alertNormal, tid, msg)
    stopChat(tid)

    -- 마지막 메시지가 유저 메시지일 때만 지운다. AI 메시지는 건드리지 않는다.
    local chatS = getFullChat(tid)
    if chatS and #chatS > 0 and chatS[#chatS].role == "user" then
      pcall(removeChat, tid, #chatS - 1)
    end

    pcall(reloadDisplay, tid)
    return
  end

  initDefaults(tid)
  refreshLabels(tid)

  local chat = getFullChat(tid)
  if not chat or #chat == 0 then return end
  for i = #chat, 1, -1 do
    if chat[i].role == "user" then
      local ooc = buildOoc(tid)
      -- 이미 붙어 있는 블록을 먼저 걷어낸다.
      -- 리롤은 같은 유저 메시지를 두고 onStart 를 다시 돌리므로,
      -- 걷어내지 않으면 블록이 두 겹 세 겹으로 쌓인다.
      local base = stripOoc(chat[i].data or "")
      if ooc ~= "" then
        setChat(tid, i - 1, base.."\n\n"..ooc)
      elseif base ~= (chat[i].data or "") then
        setChat(tid, i - 1, base)
      end
      break
    end
  end
end

-- 지난 턴 블록 제거 (히스토리·토큰 오염 방지)
listenEdit("editRequest", function(tid, data)
  if not data then return data end
  -- OOC 블록만 지운다.
  -- [MSJ_STATUS] 는 남긴다. AI 가 직전 턴 자기 태그를 보고
  -- 형식과 날짜·시각의 연속성을 이어받게 하기 위해서다.
  data = stripOoc(data)
  data = data:gsub("%s*%[msj_%a+::[^%]]*%]", "")
  return data
end)

