-- 자산 이름 치환은 여기서 하지 않는다.
--
-- <img src="이름"> 을 실제 자산으로 바꿔주는 것은 RisuAI 가 아니라 정규식 OUT 이다.
-- 그 정규식이 {{raw::}} 를 붙여줘야 URL 이 된다. 그런데 LUA editDisplay 는
-- 정규식보다 먼저 돌기 때문에, 여기서 이름을 FNPC 로 바꿔놓으면
-- 정규식의 Female[1-4] 패턴이 빗나가 {{raw::}} 가 아예 안 붙고 엑박이 된다.
--
-- 그래서 슬롯 → 자산 치환은 정규식 OUT 안에서 한다.
--   {{raw::FNPC{{getvar::{{replace::$1::Female::w}}_code}}_$2}}
-- 아래 NSFW 제거만 여기 남는다. 태그를 통째로 지우는 일이라
-- 이름이 아직 Female[1-4]_ 인 이 시점이 오히려 맞다.

local PANEL_RECENT = 5

listenEdit("editDisplay", function(tid, data, meta)
  if not data then return data end

  -- NSFW 스프라이트 제거가 먼저다. 태그를 통째로 지워야 하므로 이쪽만
  -- 태그 모양을 본다. 이름이 아직 Female[1-4]_ 라 패턴이 고정된다.
  -- 따옴표는 겹/홑/생략을 모두 받는다. 모델이 지시를 어기는 자리다.
  if setOpt(tid, "msj_nsfw") == "0" then
    data = (data:gsub('<img[^>]-src%s*=%s*["\']?([^"\'>%s]+)["\']?[^>]*>[ \t]*', function(src)
      if isNsfwSrc(src) then return "" end
      return nil
    end))
  end

  local chatLen  = getChatLength(tid) or 0
  local msgIdx   = (meta and meta.index) or (chatLen - 1)
  local isRecent = (chatLen - 1 - msgIdx) < PANEL_RECENT

  -- OOC 블록부터 걷어낸다. 순서가 중요하다.
  -- 이 블록 안에는 [MSJ_STATUS::...] 형식 예시와 [msj_aff::...] 태그 예시가 들어 있다.
  -- 먼저 지우지 않으면 OOC 가 박힌 유저 메시지가 상태창·카드를 달고 나온다.
  -- 백틱으로 감싸 나오면 마커가 코드 조각이 되어 패턴에 안 걸린다.
  -- 먼저 벗겨내고 지운다.
  data = data:gsub("```%s*(%[MSJ_PROMPT_START%])", "%1")
  data = data:gsub("(%[MSJ_PROMPT_END%])%s*```", "%1")
  data = data:gsub("`(%[MSJ_PROMPT_[%a]+%])`", "%1")
  data = stripOoc(data)

  -- 이 메시지가 AI 응답인가.
  -- 카드·상태 패널·상태창은 전부 char 메시지에만 붙인다.
  -- editDisplay 는 유저 메시지에도 호출되므로 역할을 직접 확인해야 한다.
  local mrole  = getChat(tid, msgIdx)
  local isChar = (mrole ~= nil) and (mrole.role == "char")

  local hasStatus = isChar and (data:find("[MSJ_STATUS::", 1, true) ~= nil)
  -- 태그 공백 정규화. [ msj_aff:: ... ] 처럼 와도 잡는다.
  data = data:gsub("%[%s*(msj_%a+::[^%]]-)%s*%]", "[%1]")

  -- 상태 변동 카드. 축이 몇 개든 카드 한 장으로 합친다.
  -- 태그를 전부 걷어 msjRows 에 모으고, 첫 태그 자리에만 마커를 남긴 뒤
  -- 마지막에 그 마커를 카드로 바꾼다. 카드가 본문 안 제자리에 남는다.
  local msjRows, MSJ_MARK, msjSeq = {}, "\1MSJD\1", 0
  local function msjRow(kind, nm, val, reason)
    local ax = MSJ_AX[kind]
    if not ax then return nil end             -- 모르는 축이면 태그를 건드리지 않는다
    if not (isChar and isRecent) then return "" end
    local d = tonumber(val) or 0
    if d == 0 then return "" end              -- ±0 은 bump() 도 버린다. 행도 만들지 않는다
    -- 배수는 bump() 와 같은 함수를 써야 화면 숫자와 실제 반영값이 갈라지지 않는다
    local s   = slotByName(tid, nm)
    local raw = d
    d = applyMult(tid, kind, d, s)
    if d == 0 then return "" end

    local mult = nil
    if d ~= raw then mult = tonumber(setOpt(tid, MULT_KEY[kind] or "")) end
    local p   = "w" .. s .. "_"
    -- 이름은 네 축 모두 여자 것을 쓴다.
    -- 의심은 남편 쪽 변수에 쌓이지만 이름까지 남편으로 바꾸면 카드가 두 덩이로 갈라진다.
    -- 누가 의심하는지는 "의심"이라는 축 이름이 이미 말하므로 병기할 필요가 없다.
    local who = gv(tid, p .. "name", "?")
    -- 의심 수치만 남편 쪽(h{n}_susp)에 쌓인다. 나머지는 여자 쪽에서 읽는다.
    -- 단계 이름(H_kr · L_kr · G_kr · S_kr)은 카드에 쓰지 않으므로 읽지 않는다.
    local cur
    if kind == "susp" then
      cur = gn(tid, "h" .. gn(tid, p .. "hus", s) .. "_susp", 0)
    else
      cur = gn(tid, p .. kind, 0)
    end

    msjSeq = msjSeq + 1
    msjRows[#msjRows+1] = {
      ax = ax, who = who, d = d, cur = cur,
      reason = reason, mult = mult, seq = msjSeq,
      safe = ax.fixed or (d >= 0),   -- fixed 축(의심)은 방향과 무관하게 제 색을 쓴다
    }
    return (#msjRows == 1) and MSJ_MARK or ""
  end

  -- 이름 지정형 [msj_aff::Female3::+5::사유] 과 생략형 [msj_aff::+5::사유] 을
  -- 한 번에 훑는다. 두 번 나눠 돌리면 첫 태그가 어느 쪽이었느냐에 따라
  -- 마커 자리가 어긋난다. 사유에 :: 가 들어있어도 뒤를 다시 붙여 살린다.
  data = data:gsub("\n?%[msj_(%a+)::([^%]]*)%]", function(k, body)
    local seg = {}
    for x in (body .. "::"):gmatch("(.-)::") do seg[#seg+1] = x end
    if #seg < 2 then return "" end
    if seg[1]:match("^[%+%-]?%d+$") then
      return msjRow(k, nil, seg[1], table.concat(seg, "::", 2))
    end
    if #seg < 3 then return "" end
    return msjRow(k, seg[1], seg[2], table.concat(seg, "::", 3))
  end)

  -- 행 순서는 태그가 나온 순서가 아니라 인물 등장순 · 호감·음란·죄책·의심 고정순이다.
  -- AI 가 턴마다 태그 순서를 바꿔 뱉는데 그대로 그리면 행이 자리를 옮겨,
  -- 위치로 읽던 사람이 매번 다시 찾아야 한다.
  -- table.sort 는 안정정렬이 아니므로 seq 로 마지막 끝을 묶어준다.
  if #msjRows > 1 then
    local worder = {}
    for _, r in ipairs(msjRows) do
      if not worder[r.who] then worder[r.who] = r.seq end
    end
    table.sort(msjRows, function(x, y)
      if worder[x.who] ~= worder[y.who] then return worder[x.who] < worder[y.who] end
      if x.ax.ord ~= y.ax.ord then return x.ax.ord < y.ax.ord end
      return x.seq < y.seq
    end)
  end

  -- 치환문자열로 넣지 않고 함수로 넣는다.
  -- 사유에 % 가 섞여 있으면 gsub 가 치환 지시자로 읽는다.
  local msjCard = buildMsjDeltaCard(msjRows, setOpt(tid, "msj_dcfold") == "1")
  data = data:gsub(MSJ_MARK, function() return msjCard end, 1)
  data = data:gsub(MSJ_MARK, "")

  -- 형식이 깨진 태그 정리
  data = data:gsub("\n?%[msj_%a+::[^%]]*%]", "")

  data = data:gsub("\n?%[MSJ_STATUS::.-%]", "")

  -- 최근 턴 밖이면 여기서 끝낸다
  if not isRecent then return data end

  -- 최신 판정: 마지막 char(AI) 메시지 기준
  local lastCharIdx = chatLen - 1
  for i = chatLen - 1, 0, -1 do
    local m = getChat(tid, i)
    if m and m.role == "char" then lastCharIdx = i break end
  end
  local isLatest = (msgIdx == lastCharIdx)

  -- 상태 패널: 최신 메시지에만. 현재 상태를 보여주는 것이라 과거에 붙으면 혼동된다.
  if isChar and isLatest then
    data = data .. buildStatPanel(tid)
  end

  -- STW: 최근 N턴. 그 시점의 시각·장소라 과거에도 남는 것이 맞다.
  if hasStatus then
    data = data .. buildStw(tid)
  end

  -- 설정 팝업: 최신 메시지에만. 승인연애와 같이 열림 변수로 제어한다.
  if isChar and isLatest and getChatVar(tid, "set_open") == "1" then
    data = data .. buildSetPopup(tid)
  end

  -- 캐릭터 설정 팝업: 마커만 놓는다. 실제 HTML 은 정규식이 채운다.
  -- 화면을 LUA 로 한 벌 더 만들지 않기 위해 선택기는 정규식 한 곳에만 둔다.
  --
  -- 첫 메시지에 그대로 두면, RisuAI 가 화면 밖 메시지를 렌더하지 않으므로
  -- position:fixed 오버레이가 붙을 DOM 자체가 없어 첫 메시지까지 스크롤해야 보인다.
  -- 환경세팅 팝업이 멀쩡한 이유도 같다. 그쪽은 처음부터 최신 메시지에 붙는다.
  --
  -- 첫 메시지 쪽 마커는 첫 메시지가 직접 CBS 로 끈다.
  --   {{#when::{{getvar::char_pop}}::isnot::1}}@MSJ_SETUP@{{/when}}
  -- 파이프라인이 LUA -> CBS -> 정규식 순서라, char_pop=1 이면 첫 메시지 마커가
  -- 정규식에 닿기 전에 사라진다. 여기서는 붙이는 일만 한다.
  if isChar and isLatest and getChatVar(tid, "char_pop") == "1" then
    data = data .. "\n@MSJ_SETUP@\n"
  end

  return data
end)
